Ceviri.ekle("uk","olay",{
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Припинення існування Хорезмської РСР і Бухарської Народної Радянської Республіки внаслідок національного розмежування — утворення Узбецької та Туркменської РСР", "e8c8ab4f"], "d": ["За радянським рішенням про «національне розмежування» (національно-територіальне розмежування) Хорезмську Радянську Соціалістичну Республіку та Бухарську Народну Радянську Республіку скасували; їхні землі поділили між новоутвореними Узбецькою та Туркменською Радянськими Соціалістичними Республіками (схід Хіви — Узбекистану, захід — Туркменістану). Стаття TDV `harizm`: «1924 року східні частини Хівинського ханства було передано Узбецькій Радянській Соціалістичній Республіці, а західний бік — Туркменській Радянській Соціалістичній Республіці». — подає лише рік.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Продаж Аланьї мамлюцькому султанові Барсбею", "c8bd35f2"], "d": ["Аланья, яку 1293 року захопив караманський Меджддін Махмуд-бей, перетворилася на окремий бейлік, яким управляла одна з гілок Караманідів; Ібн Баттута 1333 року зазначає, що управління було в руках караманського Юсуф-бея. 1427 року Караман ібн Савджі-бей продав місто за п'ять тисяч золотих мамлюцькому султанові Барсбею, і Аланья перейшла під мамлюцьке управління. Так цей ключовий середземноморський порт у мамлюцьких руках став перешкодою на шляху османів на південь; коли 1471 року Ґедік Ахмед-паша обложив місто, останній бей Килич-Арслан його здав.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Відібрання Табарки в генуезців — кінець коралової концесії Ломелліні", "b1f33eb5"], "d": ["Після угоди Карла V з туніським беєм 1544 року генуезька родина Ломелліні оселилася на острові Табарка й двісті років тримала коралову концесію; острів залишався християнською торговельною факторією посеред османського Тунісу. Алі-паша з династії Хусейнідів, дізнавшись про намір родини позбутися острова, послав сили й 12 червня 1741 року захопив його; близько півтори тисячі християн переселили в Туніс. Відтоді Табарка перейшла під управління Туніського оджаку.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Битва біля пірамід і взяття Каїра французами", "3ddd6b96"], "d": ["Наполеон рушив від Александрії вздовж Нілу на південь і 21 липня 1798 року біля Імбаби, навпроти Ґізи, зустрів мамлюцьку кінноту Мурад-бея. Французька піхота, побудована в каре, відбила кінні атаки; мамлюцьке військо розсіялося, і через два дні Каїр здався без опору. Мурад-бей відступив у Верхній Єгипет, а Ібрагім-бей — у Сирію. У Каїрі французи створили диван і намагалися вести управління через улемів; у жовтні 1798 року та березні 1800 року спалахнули два великі каїрські повстання.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Облога Акри Наполеоном — зупинення Сирійського походу", "d2a947ad"], "d": ["Бажаючи розгромити сили, які османи готували для повернення Єгипту, Наполеон на початку 1799 року рушив у Сирію; 18 лютого він узяв Ель-Аріш, у березні — Яффу, а 18 березня 1799 року обложив Акру. Оборона Джеззара Ахмеда-паші та підтримка з моря британського адмірала Сіднея Сміта впродовж двох місяців ламали облогу; оскільки облогові гармати захопили на морі, подолати мури не вдалося. У травні Наполеон відступив, і ця поразка позначила крайню точку французької окупації.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Заснування держави еміра Абд аль-Кадіра — централізація опору на заході Алжиру", "9e482383"], "d": ["Опір, який розпорошився після падіння Алжиру, згуртувався навколо молодого Абд аль-Кадіра, сина кадирійського шейха Мухіддіна; 22 листопада 1832 року поблизу Маскари племінні вожді присягнули йому з титулом «еміра правовірних». Створений ним устрій був не племінним союзом, а регулярною державою: вона мала монетний двір, порохову майстерню, податковий лад і столицю в Тагдемпті. За Тафнським договором 1837 року Франція офіційно визнала його владу. Абд аль-Кадір шукав захисту не в османів, а під сюзеренітетом марокканського султана Абд ар-Рахмана; тобто після 1832 року ці землі не були в османському підданстві. 23 грудня 1847 року він капітулював, і того самого року Османська держава оголосила, що її права на Алжир припинилися.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Падіння Константини — кінець східноалжирського бейства", "159fed36"], "d": ["Після падіння Алжиру 1830 року східне бейлербейство не розпалося: останній бей Ахмед зберіг власне управління в Константині й оголосив, що діє від імені османів. Перший похід французів 1836 року закінчився розгромом; другий похід 6 жовтня 1837 року обложив місто, командувач Дамремон 12 жовтня загинув від гарматного вогню, а 13 жовтня мури було подолано, і місто взяли вулиця за вулицею. Ахмед-бей відступив у гори й здався лише 1848 року. Ця дата є фактичним кінцем трьохсотлітнього османсько-турецького управління на сході Алжиру.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Завоювання області Така та заснування Кассали", "cc3e0631"], "d": ["Правитель Судану Ахмед-паша Абу Відан 1840 року підпорядкував єгипетському управлінню область Така між річками Атбара та Гаш і заснував місто Кассалу як військову ставку. Місто стало центром мудирії, що контролювала караванний шлях між Сеннаром і Суакіном та прикордонну смугу з Абіссинією.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Французька окупація Маскари (Муаскара) — втрата столиці Абд аль-Кадіра", "bd363c05"], "d": ["З призначенням Бюжо губернатором 1841 року французька стратегія змінилася: замість утримуватися на узбережжі — по черзі окуповувати внутрішні міста. Рухомі колони, що вирушали з Орана, Мостаганема та Медеа, захопили осередки регулярної держави Абд аль-Кадіра; найважливішою з них була Маскара, справжня столиця з монетним двором, пороховою майстернею та зерновими складами. Відтоді емір відмовився створювати постійний центр і перетворив своє військо на кочовий табір, який називали «смала».", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Окупація долини Шеліфу та Тенеса — заснування Орлеанвіля", "e1eeeb68"], "d": ["Щоб переслідувати Абд аль-Кадіра, французи у квітні 1843 року заснували посеред долини Шеліфу нове місто Орлеанвіль; того самого року окупували й прибережний порт Тенес. Так внутрішній коридор між Алжиром і Ораном перейшов під французький контроль, а опір у горах Дахра було оточено. 16 травня того самого року кочовий табір Абд аль-Кадіра «смалу» випадково виявили та розігнали.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Заснування укріпленого табору Сіді-Бель-Аббес", "fb33ec29"], "d": ["12 червня 1843 року Бюжо наказав генералові Бедо заснувати в Сіді-Бель-Аббесі укріплений табір із ровом і мурами; будівництво почалося 18 червня, а в листопаді того самого року тут розмістився батальйон Іноземного легіону. Табір став постійною базою, що контролювала внутрішню рівнину між Ораном і Тлемсеном.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Перехід Недроми та прикордонної смуги з Марокко під французький контроль", "61d821f3"], "d": ["Після того як 1843 року Абд аль-Кадір відступив у Марокко, Недрома на північний захід від Тлемсена та узбережжя Трара перейшли під французький контроль. Битва при Іслі 14 серпня 1844 року розгромила марокканську армію, і кордон між двома країнами провели угодою в Лалла-Магнії 18 березня 1845 року; Недрома залишилася на алжирському боці цієї лінії.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Падіння Лагуата — відкриття воріт Сахари", "b161b32c"], "d": ["Генерал Пелісьє з шеститисячним загоном 21 листопада 1852 року обложив Лагуат, і 4 грудня місто впало після кривавого штурму. Лагуат був оазисним містом, що тримало прохід між Теллем і Сахарою; його падіння відкрило французькому наступу пустельні караванні шляхи та підготувало ґрунт для того, щоб за рік мзабську конфедерацію обклали даниною.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Приєднання області Богос (Керен) до Єгипту", "b2ab83ce"], "d": ["Вернер Мунцінгер-паша, губернатор вілаєту «Східний Судан і узбережжя Червоного моря», який хедив Ісмаїл створив на західному березі Червоного моря, 1872 року приєднав до Єгипту область Богос, де жив народ білін, із центром у Керені. Це було найтриваліше просування Єгипту на край Абіссинського плоскогір'я, і воно започаткувало прикордонну суперечку з Абіссинією, яка тривала дванадцять років.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Приєднання Дарфурського султанату до Єгипту — Зубайр-паша увійшов в Ель-Фашер", "f41268ed"], "d": ["Зубайр Рахма-паша, який зміцнів на торгівлі слоновою кісткою та рабами, 25 жовтня 1874 року під Манаваші зі своїми силами, озброєними гвинтівками Ремінгтона, розігнав фурське військо; султан Ібрагім загинув у битві. 2 листопада Зубайр без бою увійшов в Ель-Фашер, і правління династії Кейра, що тривало з 1603 року, фактично припинилося. Так Дарфур приєднали до суданських провінцій Єгипту Мехмеда Алі з Кавали; проте опір родини Кейра в горах тривав до 1891 року.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Анексія оаз Мзабу (Гардая)", "9372959f"], "d": ["Ібадитські міста Мзабу 1852 року погодилися платити Франції данину, але зберегли внутрішнє управління; через тридцять років, 1882 року, область безпосередньо приєднали до французьких земель, а Гардаю підпорядкували військовому управлінню. Так юридично припинив існування й останній автономний пояс північної Сахари.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Бомбардування Александрії та британська висадка", "18d57bf8"], "d": ["Коли офіцерський рух під проводом Арабі-паші взяв хедива під контроль, Англія втрутилася під приводом безпеки Суецького шляху. Ескадра адмірала Сеймура 11-12 липня 1882 року бомбардувала берегові батареї Александрії; після пожежі та грабунків у місті 15 липня британські частини висадилися на берег. Османська держава не змогла перешкодити цій операції у вілаєті, над яким юридично була суверенною, і не відповіла на заклик узяти участь в інтервенції. Так було зроблено перший крок окупації, що тривала тридцять два роки.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Битва при Тель-ель-Кебірі — розгром війська Арабі", "8e38fecf"], "d": ["Вулслі, висадивши свої сили через Суецький канал в Ісмаїлії та провівши їх пустелею, на світанку 13 вересня 1882 року напав на єгипетські окопи при Тель-ель-Кебірі; битва закінчилася за годину. Наступного дня Арабі здався, а британська кіннота того самого дня увійшла в Каїр. Відтоді фінансові, військові та зовнішні справи Єгипту фактично перейшли під британський контроль; османський же суверенітет юридично тривав до 1914 року.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Конвенція в Ла-Марсі — завершення протекторату над Тунісом", "71338640"], "d": ["За Бардоським (Каср ас-Саїдським) договором від 12 травня 1881 року зовнішні справи Тунісу передавалися Франції, а внутрішнє управління залишалося беєві; через два роки, 8 червня 1883 року, підписана конвенція в Ла-Марсі передала під французький контроль також фінансові та адміністративні реформи й завершила оформлення протекторату. Османська держава зберігала претензію на суверенітет над Тунісом і ніколи не визнала окупації, але не змогла зробити жодного фактичного кроку проти неї. Так Туніс, османський оджак із 1574 року, офіційно перейшов під французький протекторат.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Розгром під Шейканом — знищення армії Гікс-паші", "a0e08986"], "d": ["Гікс-паша, британський офіцер у відставці, який командував надісланими з Каїра приблизно десятьма тисячами єгипетських воїнів, просуваючись кордофанською пустелею без води та провідників, 5 листопада 1883 року під Шейканом був оточений силами Махді, і армію майже повністю знищили. Цей розгром переламав хребет єгипетського управління в Судані: за місяць здалися Дарфур і Бахр-ель-Газаль, а весь Кордофан перейшов до Махді. Звідси починається шлях до падіння Хартума.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Перехід Дарфуру до сил Махді — капітуляція Слатін-паші", "6d8992d4"], "d": ["Генерал-губернатор Дарфуру Слатін-паша з 1882 року боровся з махдистським повстанням племені різейгат; вважаючи, що поразки його воїнів пояснюють тим, що він християнин, 1883 року він відкрито прийняв іслам і взяв ім'я Абд аль-Кадір. Після знищення армії Гікс-паші в Кордофані в листопаді 1883 року опір утратив сенс, і 23 грудня 1883 року він здався емірові Мадіббо. Невеликі єгипетські пости в Дарфурі незабаром пішли тим самим шляхом; десятирічне турецько-єгипетське управління закінчилося. Із цією подією гори Джебель-Марра (Дарфур) перейшли під управління Держави махдистів.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Перехід Зейли та сомалійського узбережжя під британське управління", "1d649502"], "d": ["Коли махдистське повстання зруйнувало єгипетські гарнізони в Судані та на Червоному морі, Каїр змушений був залишити свої віддалені пости на абіссинському узбережжі. 1884 року британська адміністрація в Адені висадила війська в Зейлі та Бербері; наступного року з вождями сомалійських племен підписали договори про протекторат і заснували Британське Сомаліленд. Так було втрачено Зейлу, яка з 1559 року була підпорядкована еялету Хабеш.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Капітуляція гарнізону Фашера перед махдистами", "68f0760d"], "d": ["Навіть після капітуляції Слатіна 23 грудня 1883 року єгипетський гарнізон фортеці Фашер чинив опір. Утративши під час семиденної облоги колодязі, гарнізон здався 15 січня 1884 року; зброю склали, і фортеця перейшла до махдистів.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Договір Г'юетта (Адуанський) — передання Богосу Абіссинії", "0de1b701"], "d": ["Коли махдистське повстання оточило єгипетські гарнізони в Судані, Англія, щоб отримати допомогу Абіссинії, 3 червня 1884 року підписала в Адуа договір із Йоганнесом IV. Друга стаття договору повертала Богос Абіссинії, а Абіссинія натомість відкривала шлях для евакуації оточених гарнізонів через Массауа. Так Керен вийшов з-під дванадцятирічного єгипетського управління; за п'ять років область приєднають до італійської Еритреї.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Повернення Донголи — початок Нільського походу", "f63aa14f"], "d": ["Після поразки італійців під Адуа Англія повела єгипетську армію під командуванням Кітченера вздовж Нілу на південь. У міру того як залізниця просувалася пустелею, проблему постачання було розв'язано, і 23 вересня 1896 року провінцію Донгола повернули. Тут закінчилося одинадцятирічне махдистське управління; похід тривав ще два роки й дійшов до Омдурмана.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Битва при Омдурмані — падіння Держави махдистів", "28dff7b2"], "d": ["Англо-єгипетська армія Кітченера, озброєна артилерією та кулеметами, 2 вересня 1898 року під Омдурманом за кілька годин розгромила сили халіфа Абдаллаха ат-Таайші. Наступного дня увійшли в Хартум і підняли прапор над палацом, де тринадцять років тому вбили Гордона. Столиця Держави махдистів упала; халіфа вбили наприкінці 1899 року під час операції переслідування. Фактична влада переходить саме цього дня — а 19 січня 1899 року є договором, що встановив юридичні рамки управління. Із цією поразкою Держави махдистів Дарфур (Ель-Фашер, Ньяла, Генейна, Кутум та ін.) перейшов до Дарфурського султанату, відновленого Алі Дінаром.", "ad27827a"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Італійська висадка в Тобруку — перша окупація в Триполітанії", "44780018"], "d": ["29 вересня 1911 року Італія оголосила війну, а її флот 25-26 вересня блокував узбережжя. Першу суходільну операцію провели 8 жовтня в Тобруку: невеликий османський гарнізон відступив углиб країни, і порт зайняли без бою. Тобрук був найближчим до єгипетського кордону османським портом; його падіння відкрило східний фланг Киренаїки й полегшило італійським силам похід уздовж узбережжя на захід.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Капітуляція міста Триполі перед італійцями", "785091ad"], "d": ["Триполі після триденного бомбардування капітулювало 9 жовтня 1911 року. Замість обороняти місто османські сили вирішили відступити в Азізію та Гар'ян і організувати опір у внутрішніх районах; цей опір, у якому брали участь Енвер-бей і Мустафа Кемаль-бей, до кінця війни замикав італійців у прибережній смузі. Тобто, хоч місто й упало, внутрішня частина вілаєту залишалася під османським контролем.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Втрата Дерни внаслідок італійської висадки", "f014c741"], "d": ["Після Тобрука настала черга другого порту Киренаїки — Дерни; місто окупували 16 жовтня 1911 року. Плоскогір'я навколо Дерни було областю, де тарикат сенусійя був найсильнішим, і муджахіди, зібрані на заклик шейха Ахмеда Шаріфа до джихаду, тримали італійців в облозі навколо порту. Окупація обмежилася містом і так і не змогла поширитися на його тил.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Італійська висадка в Бенгазі — втрата центру санджаку Киренаїка", "f9183c40"], "d": ["Бенгазі, центр Киренаїки, окупували 21 жовтня 1911 року внаслідок четвертої й найважливішої висадки на узбережжі. Так через три тижні після оголошення війни Італія тримала в руках усі великі порти вілаєту Триполітанія (Триполі, Тобрук, Дерну, Бенгазі), але в тил жодного з них увійти не змогла. Решта року війни минула в безрезультатних наступах із цих чотирьох прибережних пунктів углиб країни.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Односторонній декрет Італії про анексію", "cfe3f9c2"], "d": ["5 листопада 1911 року, коли ще тривала війна, Італія видала декрет, у якому оголосила, що анексувала Триполітанію та Киренаїку. Османська держава цього не визнала, і війна тривала ще рік; юридичної чинності анексія набула лише за Ушійським договором 18 жовтня 1912 року. Тому декрет не змінює османського кольору на карті — юридичне володіння залишається за османами до 1912 року, а італійський контроль показано як заштриховану окупацію.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Взяття Кьопрюхісара та підготовка до заснування Єнішехіра", "39abff03"], "d": ["Захопивши фортеці на перевалах між Бурсою та Ізніком, заклали основу передової ставки, яка мала взяти обидва міста в облогу.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Заснування Єнішехіра", "d3275837"], "d": ["Для керівництва облогами Бурси та Ізніка було засновано перше регулярне османське гарнізонне поселення; тут народився Орхан Газі.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Перша облога Ізніка та завоювання Мармараджика", "cdca2349"], "d": ["Ізнік уперше взяли в облогу, але здобути не змогли (остаточне завоювання — 1331 року); тоді ж взяли сусідню фортецю Мармараджик.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Анатолійський похід каталонських загонів", "4fd940d5"], "d": ["Каталонська компанія, найнята Візантією, щоб зупинити турецький наступ, здобула тимчасові успіхи, але надовго не затрималася; з її відходом наступ прикордонних бейліків прискорився.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Кьосе Міхал приймає іслам і приєднується до османів", "ca0d86e1"], "d": ["Текфур Харманкаї Кьосе Міхал, прийнявши іслам, разом зі своєю фортецею та людьми приєднався до Османа Газі; він став першим османським полководцем візантійського походження.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Орхан-бей фактично перебирає правління", "6dadbefc"], "d": ["Через старість і хворобу Османа Газі фактичне керівництво облогою Бурси та походами перейшло до його сина Орхан-бея (офіційне сходження на престол — 1326 року).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Взяття Муданьї", "0a623368"], "d": ["Узявши Муданью, порт Бурси, перерізали зв'язок міста з морем; облога Бурси перейшла на стадію удушення.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Перехід Акьязи та острова Імрали в руки османів (дати в джерелах немає)", "380c60ce"], "d": ["За доби Осман-бея (у роки після походу 1305 року) Акьязи стала мішенню османських набігів; точний рік остаточного взяття невідомий. Коли було взято острів Імрали, не повідомляє жодне джерело. Кордон 1324 року на карті є тимчасовим заповнювачем.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Акча Коджа захопив Кандиру та околиці", "341bb97e"], "d": ["Акча Коджа, один із прикордонних беїв Орхана Газі, здійснюючи набіги на околиці Ізміта зі своєї ставки на захід від озера Сапанджа, близько 1326 року захопив Кандиру та її околиці. Ізміт тоді ще був у руках Візантії; місто впаде лише 1337 року.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Приєднання Ялови та Карамюрселя", "133cb07a"], "d": ["Того року Ялова та її околиці на південному узбережжі Ізмітської затоки перейшли в руки турків; прибережну смугу Орхан-бей віддав як тімар Карамюрселу Ґазі.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Акча Коджа взяв Айдос і замок Самандира", "ce4daa8a"], "d": ["Після взяття Кандири Акча Коджа разом із Конуралпом і Ґазі Абдуррахманом взяв фортецю Айдос поблизу Картала, а потім замок Самандира на північ від неї; Самандирський край віддали йому у власність. Акча Коджа помер 1328 року поблизу Кандири; прикордонне бейство краю передали шехзаде Мураду.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Союз османів, Айдинідів і Саруханідів", "9df6bb74"], "d": ["Три бейліки діяли спільно проти Візантії; флот Умур-бея з роду Айдинідів набігами на фракійське узбережжя виснажував Візантію на другому фронті.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Завоювання Гемліка (Кіоса)", "66fc4bcd"], "d": ["Прибережне місто Гемлік (Кіос) біля Гемлікської затоки, що виходить у Мармурове море, перейшло в руки османів. Коли 1326 року здалася Бурса, міського текфура з родиною відіслали до Гемліка; отже, 1326 року Гемлік ще був у руках Візантії. Окремої дати для Армутлу не знайдено; його прив'язано до ланцюга Гемліка.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Шлюб Орхана Газі та Феодори: візантійський союз", "9b67a590"], "d": ["Орхан Газі, який підтримав Кантакузина в боротьбі за візантійський престол, одружився з його донькою Феодорою; цей союз дав османським силам змогу ближче ознайомитися з Румелією.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Взяття Анкари", "49bf1f6d"], "d": ["Анкара, якою управляли ахі, перейшла під османське управління; відкрився шлях у Центральну Анатолію. Інші місця, приєднані тоді ж: Сіврігісар, Чанкири.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Просування у Фракії за часів Сулеймана-паші: Малкара, Іпсала та Текірдаг", "fb31cf02"], "d": ["Створивши плацдарм у Галліполі, Сулейман-паша, вийшовши з півострова на північ, крок за кроком захопив рівнину між узбережжям Мармурового моря та гирлом Мариці. Так Малкара, Іпсала та Родосчук (Текірдаг) утворили нерозривний коридор, що з'єднував Галліполі з долиною Мариці. Без цього коридору на Едірне йти було неможливо; просування, що зупинилося через раптову смерть царевича 1357 року, продовжать Лала Шахін і Хаджі Ільбей.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Викрадення шехзаде Халіля", "b52ac3d7"], "d": ["Молодшого сина Орхана Газі, Халіля, викрали фокейські пірати; криза з викупом роками займала османо-візантійські відносини.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Перерізання шляхів допомоги Едірне: фортеці Чорлу, Люлебургаз, Бабаескі та Кешан", "8e8ad485"], "d": ["Шехзаде Мурад, відновивши завойовницький похід після визволення Халіля, щоб ізолювати Едірне від можливої допомоги ззовні, послав акинджі аж під Константинополь. Було захоплено фортеці Чорлу, Люлебургаз і Бабаескі на дорозі Константинополь—Едірне та Кешан на дорожньому вузлі Південної Фракії. Здача Едірне настала після того, як це кільце облоги було завершене.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Взяття Дімотіки — відкриття долини Мариці", "b59aee83"], "d": ["Було взято Дімотіку (Дідімотіхо), ключову фортецю долини Мариці; так відкрився шлях до завоювання Едірне. Іти на Едірне, не завершивши коридор, що тягнувся на північ від Галліполі, було неможливо, тому в послідовності румелійських завоювань ця фортеця передує Едірне. Місто на певний час стало румелійською ставкою султанів. Сили, що взяли Дімотіку, згодом разом із невеликими фортецями, як-от Кулелі-Бурґаз (Піфіон), узяли під контроль увесь район середньої Мариці.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Втрата Галліполі (Савойський хрестовий похід)", "00e7e415"], "d": ["Флот Амадея Савойського, кузена візантійського імператора, взяв Галліполі й передав його Візантії; османським плацдармом у Румелії десять років керували з того боку протоки. Інші поселення, втрачені тоді ж: Чимпе.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Битва під Чірменом — контроль над долиною Мариці", "cd738d8d"], "d": ["Військо сербських володарів було розігнане нічним нападом; місцеві сербські та болгарські володарі в Македонії та Родопах один за одним почали платити данину османам — це був початок не прямого завоювання, а хвилі васалізації. В османській традиції цю битву оповідають також під назвою «Сирпсиндиґи» та під 1364 роком як нічний напад Хаджі Ільбея на військо хрестоносців, що прийшло повернути Едірне; TDV зазначає, що ця дата помилкова і що обидві оповіді стосуються тієї самої битви.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Завоювання Пловдива та Старої Загори", "e780c9ae"], "d": ["Було взято Пловдив у горішній частині долини Мариці та Стару Загору на північ від нього; Болгарське царство зробили данником. Шлях Татарпазарджик—Іхтіман між Пловдивом і Софією залишився в руках місцевих володарів, які після Чірмена стали васалами. Інші поселення, втрачені тоді ж: Хасково, Клокотниця.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Васальна Візантія: Іоанн V у війську Мурада I (наслідок перемоги під Чірменом 1371 року)", "13ffe568"], "d": ["За TDV, після перемоги під Чірменом (на Мариці) 26 вересня 1371 року Візантійська імперія визнала османську владу і, погодившись платити данину та служити в османському війську, опинилася в становищі васальної держави. Імператор Іоанн V за цим зобов'язанням 1373 року приєднався до війська Мурада I; його син Андронік IV, якого він тоді залишив у Константинополі, разом із шехзаде Савджі-беєм із Бурси повстав проти своїх батьків.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Повернення Галліполі", "5f96c0a5"], "d": ["Андронік IV, який у боротьбі за візантійський престол дістав османську підтримку, натомість повернув Галліполі; міст між Румелією та Анатолією було відновлено. Інші місця, приєднані тоді ж: Чимпе.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Ґерміянський посаг: приєднання Кютах'ї", "d6a6fe61"], "d": ["Під час шлюбу Девлетшах-хатун, доньки ґерміянського Сулейман-шаха, з Баязидом Блискавичним Кютах'я, Сімав, Тавшанли та Еґріґьоз перейшли до османів як посаг — класичний приклад розширення без війни. Інші місця, приєднані тоді ж: Афьон.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Купівля Гамідської землі: приєднання Іспарти", "4a1b6047"], "d": ["Гамідський Хусейн-бей продав частину свого бейліку (Акшехір—Бейшехір—Іспарта) Мураду I за готівку; решту Гамідської землі 1391 року анексує Йилдирим. Інші поселення, втрачені тоді ж: Ісхакли.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Завоювання Серреса", "d4d28b60"], "d": ["Було взято Серрес, ключ до Східної Македонії; Салоніки потрапили в облогове кільце. Лінія Кюстендил—Петрич—Неврокоп—Драма між Софією та Серресом на цю дату ще не була прямо приєднана: вона послідовно перейшла у васалітет у 1370-х—1383 роках, а після 1383 року — під пряме управління. Інші поселення, втрачені тоді ж: Гевгелія, Кілкіс (Авратхісар).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Завоювання Софії", "96d5f01f"], "d": ["Західні перевали Балканських гір було взято під контроль; оскільки на цю дату Серрес перебував під владою вже з 1383 року, землі Фракії та Македонії утворювали нерозривне ціле.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Завоювання Ніша", "77f5d632"], "d": ["Зі взяттям Ніша, замка долини Морави, Сербська деспотовина опинилася під прямою загрозою.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Перша здача Салонік", "96010ee9"], "d": ["Після тривалої блокади місто здалося (1403 року його повернуть Візантії, а 1430 року остаточно завоюють). Інші місця, приєднані тоді ж: Кавала. Інші поселення, втрачені тоді ж: Лангадас, Елефтеруполіс (Правіште).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Османо-генуезька ахіднаме — поновлення договору 1352 року", "be11d17a"], "d": ["З генуезькими послами з Пери було поновлено торговельну угоду 1352 року, укладену ще за Орхана Газі; податки між двома державами, поводження з полоненими та вільну торгівлю визначили наново. Це вважають першою офіційно відомою ахіднаме дружби й торгівлі між османами та генуезцями — не військовим союзом, а суто торговельною угодою.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Болгарський похід Чандарли Алі-паші: взяття Шумена та Русе", "2781c3a9"], "d": ["Фортеці Болгарського царства вздовж Дунаю було прийнято під владу за один похід; його не слід плутати з поразкою під Білечею в Боснії того ж року — це був одночасний успіх на іншому фронті. Тирново та Відін були останніми болгарськими центрами, що ще трималися.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Поразка під Білечею", "89ba0a64"], "d": ["Загін акинджі, що рушив на Боснію, потрапив у засідку під Білечею та був знищений; ця перша велика балканська невдача підбадьорила союз, що привів до Косова.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Анексія західноанатолійських бейліків: Саруханідів, Айдинідів, Ментеше", "dcc33b71"], "d": ["Три бейліки було приєднано за один раз: осередок Саруханідів — Манісу; осередок Айдинідів — Айдин (разом із верхньою фортецею Ізміра, але портова, нижня, фортеця все ще залишалася в лицарів святого Іоанна — до 1402 року); осередок Ментеше — Муглу та Мілас разом із прибережною смугою Датча—Бодрум—Мармарис—Фетхіє. Егейське узбережжя вперше опинилося в одних руках. Інші місця, приєднані тоді ж: Сьоке.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Анексія землі Теке: приєднання Анталії", "fdbeee5c"], "d": ["Землю Теке на середземноморському узбережжі приєднали до османських земель. Текеїди — це гілка, що відокремилася від Гамідидів: Фелекюддін Дюндар-бей залишив завойовану ним Анталію своєму братові Юнусу-бею, і близько 1321 року виник окремий бейлік. Тому після 1321 року Анталію та її околиці на карті показано не кольором Гамідидів, а кольором Текеїдів. Після Анкарської битви бейлік відновили, і остаточно його ліквідували лише 1423 року.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Завоювання Скоп'є", "9e5a1af5"], "d": ["Було взято осередок Вардарської Македонії; Скоп'є стало одним із головних прикордонних центрів Румелії.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Анексія Кастамону", "876330ba"], "d": ["Кастамонську гілку роду Джандаридів було ліквідовано; синопська гілка залишилася васалом. Інші місця, приєднані тоді ж: Бартин, Сафранболу, Акчакоджа, Деврек, Ефлані, Караденіз-Ереглі, Тосья.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Падіння Тирнова — анексія Болгарії", "ff666977"], "d": ["Столиця Болгарського царства впала; Болгарія перейшла під пряме османське управління. Інші місця, приєднані тоді ж: Плевен, Ловеч, Габрово.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Фортеця Ловеч перейшла до османів", "a55e87a0"], "d": ["Ловеч, одну з фортець болгарського царя Івана Шишмана, під час походу 1393 року, у якому впало Тирново, разом з іншими провінціями Шишмана приєднали до османських земель. Джерело не говорить напевно: вважають, що завоювання припало на цей рік.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Приєднання Добруджі", "478e36f2"], "d": ["Було приєднано землі Добруджі, що тягнуться до дельти Дунаю. Інші місця, приєднані тоді ж: Силістра, Констанца, Бабадаг, Балчик, Хиршова, Тулча, Мангалія, Ісакча, Тутракан, Мечин, Кючук-Кайнарджа.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Спуск у Фессалію", "8bec60dd"], "d": ["Фессалійську рівнину з осередком у Ларисі (Єнішехірі) взяли під османське управління. Інші місця, приєднані тоді ж: Трикала, Ламія (Іздін).", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Битва при Ровіне — волоський похід", "343ae7a9"], "d": ["Після кривавої битви з волоським воєводою Мірчею, наслідок якої є спірним, Волощина погодилася платити данину османам; на північ від Дунаю встановився порядок васалітету.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Завоювання Нікополя", "b9791717"], "d": ["Після битви при Ровіне проти волохів 1395 року Баязид Блискавичний узяв фортецю Нікополь на березі Дунаю; деякі анонімні болгарські хроніки зазначають, що завоювання відбулося 3 червня 1395 року. Дата завоювання в джерелах не одностайна: стаття про битву під Нікополем в «Енциклопедії ісламу» TDV повідомляє, що Баязид захопив Силістру та Нікополь під час дунайського походу 1394 року. 1396 року фортецю візьмуть в облогу під час знаменитого хрестового походу, але вона не впаде. Інші місця, приєднані тоді ж: Охрид.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Фортеця Нікополь переходить до османів", "327012c9"], "d": ["Після наскоку при Ровіне Баязид Блискавичний узяв Нікополь; болгарського царя Івана Шишмана, який сидів там як османський васал, усунули. В атласі Нікополь із цього дня позначено як такий, що перейшов від Болгарського царства до османів.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Будівництво Анадолу-Хісари", "aa259b00"], "d": ["Щоб підтримати блокаду Константинополя, на анатолійському боці Босфору збудували Ґюзельджехісар (Анадолу-Хісари) — перший постійний крок до контролю над протокою.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Анексія Відіна", "ee1ae44b"], "d": ["Після перемоги під Нікополем анексували також Відін, останнє болгарське князівство.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Перша анексія Карамана", "3cf07876"], "d": ["Завдяки перемозі при Акчаї землі Караманідів уперше приєднали до Османської держави (під час міжцарів'я вони відновляться).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Приєднання узбережжя Джаніка: Самсун", "af9c40fa"], "d": ["У вакуумі, що утворився, коли Каді Бурханеддін потрапив у полон до Караюлюка Османа-бея з Ак-Коюнлу, Баязид Блискавичний спершу підпорядкував османському управлінню край Джанік на чорноморському узбережжі. Так Самсун і його околиці стали першим чорноморським портом династії. Лінію Сівас—Токат—Кайсері у внутрішніх землях приєднають через два тижні з фактичним розпадом держави Каді Бурханеддіна.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Взяття Малатьї", "7cb6ae16"], "d": ["Було захоплено Малатью на мамлюцькому кордоні — один із кроків, що загострили напруження з Тимуром.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Тимур узяв Малатью й залишив її Караюлюку Осману — коли Тимур відійшов, її повернули Дулкадириди", "ad2ce7d8"], "d": ["Баязид Блискавичний, залишивши взяту 1399 року Малатью Насреддіну Мехмеду з роду Дулкадиридів, повернувся до Бурси. Тимур, який вступив в Анатолію 1400 року, взяв спершу Сівас та Ельбістан, а потім Малатью; місто та околиці пограбували, а управління ними залишили Караюлюку Осману, що перебував при Тимурі. Коли Тимур відійшов із краю, над Малатьєю знову запанували Дулкадириди; так османське панування скінчилося ще до Анкари.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Договір Сулеймана Челебі з Візантією: повернення Салонік", "cc503cc2"], "d": ["Сулейман Челебі, який під час міжцарів'я правив Румелією, за угодою з Візантією та латинськими державами віддав Візантії Салоніки та чорноморське узбережжя аж до Месемврії (TDV fetret-devri: Галліпольський договір, лютий 1403) — на карті Іґнеада, Резово та Ахтопол переходять до Візантії; на карті Салоніки від цієї дати виходять з-під влади османів.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Морська поразка під Галліполі (Венеція)", "b71d4d68"], "d": ["Венеційський флот завдав під Галліполі тяжкої поразки османському флоту; ця подія показала межі раннього османського мореплавства.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Повстання Дюзмедже Мустафи", "0ec43138"], "d": ["Мустафа Челебі, який видавав себе за сина Йилдирима, за підтримки Візантії проголосив себе султаном у Румелії; Мурад II придушив повстання 1422 року й наказав стратити суперника.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Облога Константинополя Мурадом II", "4b9d9fba"], "d": ["У відповідь на те, що Візантія підтримала Дюзмедже Мустафу, Мурад II обложив Константинополь; облогу зняли, коли в Анатолії підняли повстання його брата Кючюка Мустафи.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Передання Салонік Венеції", "bfa6c4a0"], "d": ["Візантійський намісник під тиском османів передав місто Венеції; почалося османо-венеційське суперництво, що триватиме сім років.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Повторна анексія західноанатолійських бейліків: Ментеше та Айдин", "aca30a48"], "d": ["Два егейські бейліки, відновлені під час міжцарів'я, за Мурада II остаточно приєднали до османських земель. За статтею TDV про Ментеше, Мурад II захопив землю Ментеше 827 (1424) року й ув'язнив двох братів, що стояли на чолі бейліку. За статтею ж про Айдинідів, бейлербей Анатолії Хамза-бей наказав схопити Джюнейда-бея, який знову вийшов із покори, і стратити його разом із родиною (829/1425-26), а землю Айдин перейшла до османів. Лицарі святого Іоанна, які з 1344 року тримали портову фортецю Ізміра, 1402 року втратили її на користь Тимура, і край повернувся під контроль Айдинідів; з цією анексією він також приєднався до османів. Земля Теке (Анталія) не є предметом цього запису: Текеїдів ліквідували окремо 1423 року. Ґерміян же приєднають 1429 року за заповітом.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Анексія Ґерміяну за заповітом", "9eb86b77"], "d": ["Ґерміянський бей Якуб II, який помер бездітним, заповів свою країну османам — хрестоматійний приклад анексії без війни. Інші місця, приєднані тоді ж: Карахісар-і Сахіб (Афьон).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Остаточне завоювання Салонік", "bc021768"], "d": ["Місто, що перебувало під венеційським управлінням, взяли штурмом; другий великий порт Румелії остаточно став османським. Інші місця, приєднані тоді ж: Кассандра (Кесендіре).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Здача Яніни", "ee45cb52"], "d": ["Яніна, осередок Епіру, здалася за угодою.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Перше взяття Смедерева", "c11ca17d"], "d": ["Після тримісячної облоги взяли столицю Сербської деспотовини, і Сербію вперше анексували (її повернуть за Едірнсько-Сеґедським договором 1444 року).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Облога Белграда (невдала)", "3e05f425"], "d": ["Перша велика облога Белграда, що тривала шість місяців, не дала результату; вісімдесят років фортеця залишалася замком на шляху османського просування.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Розгром під Златицею — «Довгий похід»", "97df1466"], "d": ["Військо, яке Гуняді посеред зими ввів на Балкани, пройшло Ніш і Софію та підступило до Златиці; османська оборона ледве встояла. Ця атмосфера розгрому посадила за стіл переговорів щодо Едірнсько-Сеґедського миру.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Едірнсько-Сеґедський договір", "0aa4e0de"], "d": ["Десятирічний мир: Сербську деспотовину відновили, Дунай визнали кордоном. Порушення договору за кілька місяців під підбурюванням папства призвело до катастрофи під Варною.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Повернення Смедерева та сербських фортець Сербії", "cda3cf9e"], "d": ["Положення Едірнсько-Сеґедського договору набуло чинності: 15 серпня 1444 року Мурад II повернув Юрію Бранковичу Смедерево разом із двадцятьма чотирма важливими фортецями та іншими окупованими сербськими землями (TDV semendire); Ніш (TDV nis), Аладжахісар (TDV alacahisar), Шехіркьой (TDV sehirkoy) і Приштину (TDV pristine) також залишили сербам. Відін, не будучи сербською землею, не увійшов до повернення — звідси та північно-західна територіальна втрата, яку видно на карті приблизно в час Варненської перемоги; через кілька місяців із розгромом під Варною договір і так втратить чинність.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Румелі-Хісари завершено — «Перерізувач протоки» (Боґазкесен)", "480e8a76"], "d": ["Із фортецею, яку, за джерелами, звели надзвичайно швидко — за чотири-п'ять місяців, — контроль над Босфором повністю перейшов до османів; шлях допомоги Константинополю з Чорного моря закрився. Це вважають фактичним першим кроком облоги.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Почалася облога Константинополя", "8af50742"], "d": ["Військо стало перед мурами; під час облоги, що триватиме 54 дні, велетенські гармати вперше систематично застосували проти мурів столиці.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Кораблі суходолом спустили в Золотий Ріг", "4f2ba07c"], "d": ["Близько 70 кораблів флоту, який не міг увійти в Золотий Ріг, перегороджений ланцюгом, перетягли на змащених жиром полозах через узгір'я Ґалати й за одну ніч спустили в Золотий Ріг; оборону було розділено на два фронти.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Завоювання Афін", "4f0f1bb2"], "d": ["Афінське герцогство припинило існування; на Акрополі підняли османський прапор. Інші місця, приєднані тоді ж: Фіви (Істефе), Лівадія.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Анексія Сербії (падіння Смедерева)", "75fd0a62"], "d": ["Смедерево, столиця Сербської деспотовини, здалося; Сербія стала османським санджаком.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Завоювання Мореї", "7d5a3c18"], "d": ["Морейський деспотат ліквідували; півострів (крім венеційських фортець) перейшов під османське управління.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Приєднання Синопа", "e03c2739"], "d": ["Джандаридський правитель Синопа здався без бою; відкрився шлях для Трапезундського походу. Інші місця, приєднані тоді ж: Кастамону, Бартин, Сафранболу. Стаття TDV про Джандаридів називає серед земель бейліку Джандаридів, анексованих 1461 року, також Болу, Ефлані та Тосью; в атласі ці три місця того ж дня записані як такі, що перейшли від Джандаридів до османів. Інші поселення, втрачені тоді ж: Караденіз-Ереглі, Деврек, Акчакоджа (землі Джандаридів).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Падіння Боснійського королівства — боснійський похід Фатіха", "5362e3f2"], "d": ["Коли останній боснійський король Стефан Томашевич (1461-1463), покладаючись на підтримку Заходу, відмовився платити данину, його стали вважати таким, що перестав бути залежним правителем, і військо під проводом султана Мехмеда Фатіха ліквідувало Боснійське королівство за один похід. Короля схопили та стратили, королівство зникло, а в краї утворили Боснійський санджак. Проте падіння королівства — не те саме, що завоювання Боснії. Османське управління в рівнині існувало вже п'ятнадцять років: Ходидєд і Сараєвську рівнину взяли 1448 року, а прикордонне бейство Іси-бея виникло посеред королівства. Завоювання не скінчилося й 1463 року: Фочу взяли 1465-го, Ливно — 1469-го, Герцогство Герцеговину — 1483-го, Сребреницький банат — 1512-го, а Яйце й Баню-Луку на півночі вдалося взяти лише 1528 року, після Мохача: угорці створили на півночі Боснії банат, який протримався шістдесят п'ять років після 1463-го. На цю дату прямо змінило власника місце Травнік; Яйце ж на цю дату перейшло не до османів, а до Угорщини.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Остаточна анексія Карамана", "f1dcecaa"], "d": ["Центральні землі Караманідів остаточно приєднали; внутрішні чвари тривали до 1470-х років. Інші місця, приєднані тоді ж: Ніґде, Мостар, Бейшехір.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Завоювання Негропонта", "5c97daf3"], "d": ["Негропонт (Еґрібоз), головна база Венеції в Егейському морі, впав.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Анексія Аланьї, Анамура та Силіфке (Ічеля)", "a0b9d461"], "d": ["Прибережну смугу Ічель, залежну від Караманідів (усе середземноморське узбережжя між Анталією та Мерсіном), приєднали морським походом Ґедіка Ахмеда-паші; Аланья була важлива своєю стратегічною верф'ю сельджуцьких часів.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Приєднання Новгорода до Москви", "bed87170"], "d": ["Великий князь Іван III зняв символічний дзвін новгородського віча, замінив місцевих урядників своїми намісниками й фактично підпорядкував місто Москві; Новгород перестав бути незалежною республікою. Новгородська земля тяглася від Балтійського моря до Білого моря та Уралу. В атласі Новгород із цього дня позначено як такий, що перейшов від Новгородської республіки до Москви.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Стамбульський договір — Албанія та Шкодер", "b09652f7"], "d": ["16-річна османо-венеційська війна скінчилася; Шкодер та албанське узбережжя залишилися за османами. Інші місця, приєднані тоді ж: Лемнос, Самос, Бозбаба (Айос-Евстратіос).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Висадка в Отранто", "7916b89d"], "d": ["Османські сили, що висадилися на узбережжі Апулії (Пульї), взяли в облогу й захопили фортецю Отранто; оскільки в місто увірвалися з боєм, частину знатних людей, які чинили опір, стратили, а частину взяли в полон. Церковна традиція вшановує загиблих як «отрантських мучеників» — близько 800 осіб; TDV пов'язує перебільшення цього числа з церковною пропагандою. Утримали лише фортецю на краю півострова Саленто та вузькі її околиці; решту земель Неаполітанського королівства на лінії Таранто—Бриндізі—Лечче втрачено не було — цей плацдарм, що відкривав шлях в Італію, проіснує рік.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Евакуація Отранто", "37371bb0"], "d": ["Гарнізон Отранто, який після смерті султана Мехмеда Фатіха (3 травня 1481) не мав надії на нове підкріплення, під облогою неаполітанського спадкоємця Альфонсо за угодою залишив фортецю; так єдиний османський плацдарм в Італії було втрачено через рік.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Завоювання Модона та Корона", "38b608c4"], "d": ["Було взято Модон і Корон, «два ока» Венеції в Мореї.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Завоювання Дурреса", "1f231b98"], "d": ["Під час османо-венеційської війни 1499-1503 років сили під командуванням Мехмеда-бея взяли Дуррес (Драч), останній великий албанський порт Венеції на Адріатиці. Після Шкодера (1479) та Вльори (1417) із цим завоюванням албанська прибережна смуга повністю перейшла під османський контроль.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Приєднання Східної Анатолії", "e0cb8f8f"], "d": ["Після Чалдирана приєднали Діярбакир та його околиці; курдські бейліки через Ідріса Бітлісі підпорядкувалися османам.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Завоювання фортеці Варадин (Петроварадин)", "abf392a5"], "d": ["Військо, що вирушило в Мохацький похід, перейшло з Белграда на угорські землі; спершу взяли зовнішні квартали Варадина, а після чотирнадцятиденної облоги впала й фортеця. Сулейман Законодавець наказав не палити села на шляху, бо ці місця вже вважалися османською землею.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Здача Буди після Мохача — два королі на угорський престол", "9d3568a0"], "d": ["Османському війську, що після перемоги під Мохачем ішло на Буду, 11 вересня 1526 року ключі міста піднесли султанові; однак Сулейман Законодавець не утримав Буду й відвів своє військо. В Угорщині, що залишилася без короля, знать обрала двох окремих королів: 10 листопада 1526 року — Яноша Запольяї, а 17 грудня 1526 року — Фердинанда I Габсбурга. У серпні 1527 року Фердинанд узяв Буду. Запольяї оселиться в Буді як король під османським протекторатом унаслідок походу 1529 року (див. запис за 1529), а пряме османське управління буде встановлене 1541 року.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["Яноша Запольяї обрано королем Угорщини — османи визнали його королівство за умови залежності", "32bc6baf"], "d": ["На угорський престол, що спорожнів після смерті короля під Мохачем, частина шляхти обрала трансильванського воєводу Яноша Запольяї; Запольяї коронувався в Секешфегерварі. Османи, які залишили Буду, щоб утримати край як буфер, визнали королівство Запольяї за умови його залежності від них. На карті місця, пов'язані із Запольяї, від цієї дати показані як залежні від османів.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Фердинанда I проголошено королем Угорщини — Західна та Північна Угорщина під габсбурзькою короною", "b3910a2f"], "d": ["Габсбурзький ерцгерцог Фердинанд, спираючись на шлюб своєї сестри з Лайошем II, заявив претензію на угорський престол, і частина шляхти проголосила його королем. Так Угорщина розділилася між двома королями; західна та північна її частини визнали Фердинанда. Хорватська шляхта окремо обрала його на початку 1527 року.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Суперництво двох королів: Естерґом — під габсбурзьким покровительством, Сеґед — за Запольяї", "da92dee5"], "d": ["Естерґом, який з 1526 року переходив із рук у руки між двома королями, після переїзду архієпископа з архівом і скарбницею на північ потрапив під габсбурзьке покровительство. Від того ж року до 1541 Сеґед залишався під владою Запольяї.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Мешканці Печа перейшли на бік Запольяї", "3fc4e7f2"], "d": ["Печ, який 1528 року отримав від Фердинанда привілей, невдовзі перейшов на бік Запольяї; король Янош 1533 року деякий час перебував у місті. З падінням Буди 1541 року місто знову повернулося на бік Фердинанда.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Завоювання Триполі", "8c659986"], "d": ["У лицарів святого Іоанна відібрали Триполі; центральне узбережжя Північної Африки стало османським. Інші місця, приєднані тоді ж: Місурата.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Завоювання Темешвара", "e9fd4995"], "d": ["Було взято край Банат і засновано Темешварський бейлербейлік.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Остаточне завоювання Туніса", "7bbd11bc"], "d": ["Туніс, що перебував під іспансько-хафсідським контролем, остаточно перейшов під османське управління; північноафриканська лінія була завершена. Інші місця, приєднані тоді ж: Кайруан, Габес, Сфакс.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Завоювання Канізи", "0c7b6aa3"], "d": ["Під час Довгої війни взяли Канізу; наступного року оборона Тір'які Хасана-паші стала легендою.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Почався Уйварський похід — Фазиль Ахмед-паша виступив з Едірне проти Австрії", "306a86db"], "d": ["Після того як Австрія напала на Трансильванію та взяла фортеці Секейхід і Коложвар, Стамбул ухвалив рішення про похід проти Габсбургів. Великий візир Кьопрюлюзаде Фазиль Ахмед-паша 13 квітня 1663 року вирушив з Едірне. У Белграді надійшло прохання Австрії про мир, але на двох зустрічах в Осієку османські умови відхилили. На нараді в Буді мішенню також визначили Уйвар.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Завоювання Уйвара", "ce289470"], "d": ["Було взято Уйвар (Нове Замки), ключову фортецю Північної Угорщини; вислів «сильний, як турок під Уйваром» увійшов у європейські мови. Після Уйвара після короткого опору здалися також Нітра та Левіце; обидві навесні 1664 року повернув Де Суш.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Повернення Мореї", "9b6460f1"], "d": ["Морею, залишену Венеції в Карловцях, повернули за один похід. Інші місця, приєднані тоді ж: Патри (Бальябадра), Лепанто (Інебахти).", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Друга втрата Белграда — облога принца Євгенія", "6a194354"], "d": ["Після розгрому під Варадином і втрати Темешвара принц Євгеній обложив Белград; коли розгромили й військо, яке прийшло визволяти місто, фортеця здалася. Так місто, повернуте 1690 року після Карловиць, було знову втрачене, а дунайська лінія оборони завалилася. Белград удалося повернути лише через двадцять два роки, за Белградським договором 1739 року. Інші поселення, втрачені тоді ж: Смедерево. Крім того, атлас записує околиці Хісарджика (Ґроцки) та Ягодини цього дня за Габсбургами (регіональна дата; дня на рівні поселення в джерелі немає, задекларована приблизність); Мехадія ж переходить до Габсбургів 27 серпня 1717 року (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Падіння Очакова", "90a67a6c"], "d": ["Очаків (Озі), ключова фортеця на північ від Чорного моря, під час кривавого штурму перейшов у руки Росії; населення міста вирізали.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Бухарестський договір — втрата Бессарабії", "932da4d6"], "d": ["За договором, що завершив російську війну 1806-1812 років, землі на схід від Прута (Бессарабію) віддали Росії. Інші поселення, втрачені тоді ж: Аккерман, Кілія, Хотин, Бендери, Ізмаїл. Крім того, атлас вважає, що Кишинів, Бєльці, Кагул і Орхей у межах Бессарабії того ж дня перейшли від Молдавії (османського васала) до Росії. Сороки також того ж дня переходять до Росії.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Адріанопольський договір", "b3a8fe4c"], "d": ["Наприкінці війни, під час якої російська армія вступила в Едірне, було втрачено дельту Дунаю; автономію/незалежність Греції фактично визнано. Інші поселення, втрачені тоді ж: Бреїла, Анапа, Ахалцихе. Хоча договір повертав землю, він не припинив окупацію одразу: Волощина-Молдавія та Силістра залишалися під російським управлінням як застава, доки не буде сплачено воєнну контрибуцію, — саме тому на карті ці місця й після 1829 року виглядають окупованими. Цим договором скінчилася й османська претензія на Черкесію (Майкоп) та черкеське узбережжя (Сочі, Туапсе); згодом узбережжя перейшло до Росії (Сочі та Туапсе — 1838).", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Указ про автономію Сербії — спадкове князювання та умова про гарнізони", "6a5d901d"], "d": ["Хатт-і хумаюн, виданий відповідно до положення Адріанопольського договору щодо Сербії, визнав Милоша Обреновича спадковим князем і зробив Сербію автономним князівством, вільним у внутрішніх справах і залежним від османів у зовнішніх. Положення: князювання переходитиме від батька до сина, щорічний податок сплачуватиметься фіксованою сумою, сербська скупщина встановить власне внутрішнє управління, церква буде автономною; натомість у фортецях Белград, Смедерево, Шабац, Соко та Ушче (Фетхюлісслам) залишаться османські гарнізони. Така двоїста структура тривала до виведення гарнізонів 1867 року. На карті місто Белград від цієї дати приєднується до автономної Сербії; фортецю Калемегдан до 1867 року показано з османським гарнізоном.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Кіпр передано під британське управління", "423da3ee"], "d": ["В обмін на союз проти російської загрози управління Кіпром передали Британії; юридично він залишався османською землею. Інші поселення, втрачені тоді ж: Нікосія, Фамагуста, Кіренія, Лімасол, Ларнака (Тузла), Пафос, Морфу, Акротірі, Епіскопі, Декелія; тобто весь острів.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Передання Фессалії Греції", "ac614d24"], "d": ["Відповідно до рішень Берлінського конгресу Фессалію та околиці Арти передали Греції. Інші поселення, втрачені тоді ж: Арта, Лариса, Трикала, Ламія. Із цим переданням Волос, Каламбака та Кардіца (Фессалія) перейшли до Греції.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Об'єднання Східної Румелії з Болгарією", "ee43f137"], "d": ["Автономний вілаєт Східна Румелія внаслідок перевороту приєднали до Болгарії; Висока Порта примирилася з доконаним фактом. Унаслідок цього об'єднання вся Східна Румелія (Стара Загора, Пазарджик, Слівен, Хасково, Бургас, Айтос, Елхово) перейшла до Болгарського князівства.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Битва під Домокосом", "9c6f29a5"], "d": ["В османо-грецькій війні 1897 року військо здобуло вирішальну перемогу під Домокосом; через дипломатичний тиск територіальне надбання залишилося обмеженим.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Автономія Криту", "2e764881"], "d": ["Хоча османо-грецька війна закінчилася османською перемогою, Британія, Росія, Франція та Італія 18 грудня 1897 року проголосили автономію Криту; острів мав стати нейтральним автономним вілаєтом під османською владою. Після 6 листопада 1898 року турецький прапор у Кандії та Кісамосі вже не піднімали; коли 22 грудня 1898 року принц Георг, син грецького короля, приступив до обов'язків надзвичайного комісара, Крит фактично вийшов з-під османського управління (офіційно відокремився 1913 року). Інші поселення, втрачені тоді ж: Кандія (Крит), Ханья.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Незалежність Болгарії та анексія Боснії", "393feaa4"], "d": ["У сум'ятті конституційної революції Болгарія проголосила незалежність, а Австро-Угорщина анексувала Боснію і Герцеговину. Із цим проголошенням усі землі Болгарського князівства (Варна, Шумен, Русе, Бургас, Слівен та ін.) стали незалежним Болгарським царством.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Повернення Едірне", "536e5599"], "d": ["Під час Другої балканської війни військо переправилося через Марицю та без бою повернуло Едірне. Інші місця, приєднані тоді ж: Киркларелі, Текірдаг.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Перемога під Кут-ель-Амарою", "98b972bc"], "d": ["Командувач британської дивізії, обложеної в Куті, здався разом зі своїми 13 тисячами солдатів — одна з найбільших османських перемог Першої світової війни.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Втрата Багдада", "2c18a816"], "d": ["Багдад, що 383 роки був османським, перейшов до британської армії. Інші поселення, втрачені тоді ж: Кербела, Кизилрубат.", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Втрата Єрусалима", "94067617"], "d": ["Єрусалим, що 401 рік був османським, здали без оборони.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Втрата Дамаска", "ed177b68"], "d": ["З крахом Палестинського фронту Дамаск евакуювали; чотири століття османського правління в Сирії скінчилися. Інші поселення, втрачені тоді ж: Хама, Хомс.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Здача Медини", "76b505f6"], "d": ["Через 72 дні після перемир'я опір Фахреддіна-паші, «Пустельного тигра», припинився за волею султана; остання османська частина в Хіджазі склала зброю.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Окупація Ізміра", "e32e5e77"], "d": ["Грецька армія висадилася в Ізмірі; опір, що почався з першої кулі, запалив ґніт Національної боротьби. Айдин же окупували 27 травня 1919 року (окремий запис).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Офіційна окупація Стамбула", "a8e98ada"], "d": ["Сили Антанти офіційно окупували Стамбул, Меджліс-і Мебусан розігнали; депутати вирушили до Анкари.", "09ed005b"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Виступ Сулеймана Законодавця у віденський похід — війна з Габсбургами відновилася", "f7afd2a9"], "d": ["Після Мохача угорський трон розділився надвоє, а 1527 р. Фердинанд узяв Буду й вигнав Запольяї зі столиці. Султан учетверте вирушив у похід, щоб підтримати Запольяї та зупинити наступ Габсбургів; перед походом великому візирові Ібрагім-паші надали титул сераскера та бейлербейство Румелії, і все планування здійснювалося разом із ним. Дорогою сильні дощі затримували просування війська; похід тривав узяттям Буди та передачею її Запольяї й облогою Відня.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Поновлення миру з Габсбургами — кінець війни за Трансильванію та Темешвар", "97071975"], "d": ["Війна, яка почалася з переходом Трансильванії до Фердинанда 1551 р. і тривала в таких походах, як завоювання Темешвара та облога Егера, завершилася рішенням про продовження миру з Габсбургами. Угода взаємно поновлювала колишні зобов'язання обох сторін; проте вона не принесла розв'язання заворушень на прикордонні, і після смерті Фердинанда 1564 р. події в Трансильванії знову почастішали.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["Останній похід Сулеймана Законодавця — виступ зі Стамбула з метою взяти Сіґетвар і Егер", "31277d21"], "d": ["Після смерті Фердинанда 1564 р. та сходження на трон Максиміліана II сутички на трансильванському прикордонні почастішали. У поході, який літній султан спланував разом із Соколлу Мехмед-пашею, цілями мали стати фортеці Сіґетвар і Егер, а імператорові слід було пригрозити. Помолившись у гробниці Еюп Султана, він з великою урочистістю залишив Стамбул; 15 травня прибув до Едірне, а на п'ятдесятий день походу дістався Белграда. Це був його останній виїзд зі столиці, якої він більше не побачив.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Едірнський договір — кінець стану війни з Габсбургами", "d08883e3"], "d": ["Перед Селімом II, який після сіґетварського походу зимував в Едірне, перебували посли Габсбургів, Сефевідів, Польщі, Франції та Венеції. Було вирішено зберегти мир із Сефевідами; підписано договір, що поклав край стану війни з Габсбургами. Великий вплив на ці справи мав великий візир Соколлу Мехмед-паша.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Рішення про іранський похід — проти Сефевідів, ослаблених смертю Тахмаспа, призначено двох сердарів", "1f09b186"], "d": ["Після того як 1576 р. шаха Тахмаспа I отруїли внаслідок чвар між членами династії та сановниками держави, Сефевіди поринули у велику смуту; це визначило напрям майбутнього походу. Лалі Мустафі-паші доручили вступити в Іран з боку Ерзурума, а Коджі Сінан-паші — з боку Багдада. Коли суперечка між двома візирами загострилася, втрутився Соколлу: Сінан-пашу усунули з посади, а Лалі Мустафі-паші доручили завоювати Ширван через Грузію. Це рішення стало початком османсько-сефевідської війни 1578-1590 рр.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Джигалазаде Сінан-паша вирушив в іранський похід", "1e90763e"], "d": ["Поки тривала війна на два фронти з Іраном та Австрією, шах Аббас обложив і взяв Реван, вступив у Карс, але його вдалося зупинити лише під Ахалцихе. Джигалазаде Сінан-паша, призначений сердаром Сходу, із запізненням вирушив зі Стамбула й 8 листопада прибув під Карс. Хоча обставини були сприятливими, він не пішов на шаха, а зазимував у Вані, а коли шах перейшов у наступ, перебрався до Ерзурума; похідний сезон було змарновано.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Поразка Джигалазаде Сінан-паші поблизу озера Урмія (Суфіян)", "7438fec4"], "d": ["Становище Сінан-паші, який у похідний сезон 1605 р. виступив, щоб повернути Тебріз, похитнулося, коли бейлербей Ерзурума Кьосе Сефер-паша став діяти окремо від головного війська й потрапив у полон. Раптовий напад шаха Аббаса завдав війську тяжкої поразки в околицях озера Урмія; Сінан-паша відступив спершу до Вана, а потім до Діярбакира. Те, що він наказав стратити бейлербея Алеппо Джанболатоглу Хусейн-пашу за запізнення з допомогою, розпалило в Анатолії велике повстання; після смерті Сінан-паші шах Аббас узяв Гянджу, Ширван і Шемаху.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Тебрізький похід Куюджу Мурад-паші — на Аджичаї бою не відбулося", "3c0a0a5d"], "d": ["Великий візир Куюджу Мурад-паша, який придушив повстання джелялі та відновив спокій в Анатолії, рушив через Ерзурум, Хасанкале, Чалдиран і Хой на шаха Аббаса, який, за отриманими вістями, чекав у Тебрізі. Два війська зійшлися в місцевості Аджичай на північ від Тебріза, але бою не відбулося; листування тривало. З наближенням зими та через брак боєприпасів і провіанту паша відступив через Ахлат, Ван і Бітліс до Діярбакира й наступного літа помер там під час підготовки нового походу (5 серпня 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["Османсько-сефевідська війна відновилася — великий візир Окюз Мехмед-паша вирушив у східний похід", "ef32fa31"], "d": ["Коли не надійшло звісток від Інджилі Мустафи Чавуша, відправленого послом до Ірану після договору Насух-паші 1612 р., великому візирові Мехмед-паші доручили східний похід, і він, завершивши приготування, переправився в Ускюдар. Саме коли він вирушав у дорогу, надійшла звістка, що Інджилі Чавуш та іранський посол Бурун Касим-хан прибули до Вана з угодою та дарами, проте похід не відклали. Великий візир перезимував в Алеппо.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Облога Ревана — знята без результату через п'ятдесят п'ять днів", "64a4ecb6"], "d": ["Великий візир, який у квітні 1616 р. виступив з Алеппо з великим військом, через Ерзурум і Карс дістався Ревана. Вважаючи, що фортеця легко здасться, важких гармат не привезли; облога тривала п'ятдесят п'ять днів за браку матеріалів. Після загибелі яничарського аги Муслу-аги та Текелі Мехмед-паші, через небажання воїнів і пізню пору року облогу зняли, і військо відійшло до Ерзурума. У листопаді 1616 р. Мехмед-пашу змістили, а його місце посів Халіл-паша.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Поразка під Серавом (Пуль-і Шикесте) — іранський похід Халіл-паші", "d323ed03"], "d": ["Халіл-паша, який став сердаром замість Окюз Мехмед-паші, 1618 р. знову пішов на Іран. Битва в місцевості Пуль-і Шикесте між Тебрізом і Ардебілем завершилася поразкою османського війська. Після цієї поразки, яку в джерелах називають також Серавською битвою, того ж місяця було підписано Серавський договір.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Лепанто повернуто османам згідно з Карловицьким миром", "9ca4f9dd"], "d": ["Лепанто, яке під час воєн 1683-1699 рр. довго чинило опір, а в липні 1687 р. разом із сусідніми фортецями дісталося Венеції, залишалося в руках венеційців ще рік після Карловицького договору, а потім повернулося османам. Фортеця біля входу в Коринфську затоку таким чином повернулася під османське управління за п'ятнадцять років до Мореї.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Топал Осман-паша переміг Надіра під Дуджейлем — облогу Багдада знято", "7ae1fc9e"], "d": ["Проти Надіра, який у січні 1733 р. обложив Багдад, виступило послане на допомогу місту військо під командуванням Топала Осман-паші, яке розбило сили Надіра в Дуджейлі поблизу Самарри; поранений Надір відступив до Хамадана, і багатомісячну облогу було знято. Але перемога виявилася недовгою: наприкінці того ж року Надір знову вторгся в Ірак і переміг османські сили в Акдербенді на північ від Кіркука; Топал Осман-паша загинув під час цих боїв і був похований у Кіркуку.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Іракський похід Надір-шаха — почалася остання османсько-іранська війна, Кіркук упав", "ba014bf5"], "d": ["Надір-шах, який вісімнадцять місяців пробув у Дагестані та Грузії і чию вимогу визнати джафаризм п'ятим мазхабом османи відхилили, 1743 р. розпочав новий похід проти османів і з великим військом вступив у Кіркук. Такого ж успіху в Мосулі він досягти не зміг і був змушений зняти облогу. Це остання османсько-іранська війна, яку завершив Керденський договір 1746 р.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Облога Карса Надір-шахом — тривала два місяці без результату", "a3ea61d9"], "d": ["Сефевідський принц Сафі Мірза, який знайшов притулок в османів, претендував на іранський трон; за планом, карський сераскер мав провести його через Тебріз до Ісфагана й посадити на трон, а османи відкрили проти Ірану три фронти. У відповідь Надір-шах пішов на Карс і обложив фортецю. Двомісячна облога не дала йому жодного результату.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Поразка під Кагавердом — військо Єгена Мехмед-паші розпалося", "7caf6f22"], "d": ["Наступного року після облоги Карса Надір-шах у місцевості Кагаверд розгромив османські сили під командуванням Єгена Мехмед-паші. Потім він повернувся до Ісфагана. Відмова від наполягання на визнанні джафаризму наступного року відкрила шлях до Керденського договору.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Захоплення емірату Хаїль саудівсько-ваххабітськими силами — управління було в руках родини Ібн Алі з клану Абде", "2d29ceb9"], "d": ["Коли сили Першої Саудівської держави захопили емірат Хаїль, містом управляла родина Ібн Алі з клану Абде племені шаммар. Ця родина правила Хаїлем до 1835 року, коли Абдаллах ібн Рашид захопив емірат; династію Рашидидів було засновано лише тоді. В атласі Хаїль досі виглядав безгосподарним аж до 1836 року, тоді як джерело 1820 року називає еміра міста на ім'я.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Перехід островів Кварнера до наполеонівського Італійського королівства, а Боки-Которської — під російське управління", "c5e411c8"], "d": ["Після Пресбурзького миру острови Кварнера — на відміну від Далмації — були приєднані не безпосередньо до Франції, а до наполеонівського Італійського королівства; до Іллірійських провінцій вони увійшли лише 1809 року. У Боці-Которській австрійське управління припинилося, і з 1806 до 1807 року там було встановлене російське управління; до Франції Бока перейшла лише 1807 року. Ці дві відмінності неможливо передати в атласі одним-єдиним «французьким» проміжком.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Перехід Далмації під французьке управління — виконання Пресбурзького (Братиславського) миру", "00bfe4f6"], "d": ["Пресбурзький (Братиславський) мир від 26 грудня 1805 року змусив Австрію відмовитися від Істрії, Далмації та всіх адріатичних островів. Франція фактично перебрала управління в лютому 1806 року; Задар залишився осередком генерального проведитора, і цю посаду з 1806 до 1810 року обіймав венеційець Віченцо Дандоло. Після Шенбруннського миру 1809 року Далмацію приєднали до Іллірійських провінцій. Так закінчилося перше австрійське управління, яке тривало з 1797 року, — в атласі ця доба досі виглядала як безперервно австрійська.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Повернення Австрією Іллірійських провінцій і Далмації — кінець наполеонівського управління", "1b2ac942"], "d": ["Наприкінці 1813 року габсбурзькі війська повернули область на південь від Сави, і стару прикордонну організацію було відновлено; австрійська армія увійшла в Істрію в жовтні 1813 року. Від того часу Карловац став частиною австрійського Іллірійського королівства. 1813 року закрилася й доба французького управління в Далмації. Належність області Австрії офіційно підтвердили рішення Паризького миру 1814 року та Віденського конгресу 1815 року. Унаслідок цієї операції Філлах, Тарвізіо, Гориція, Градишка та Пула (Іллірійські провінції) наприкінці 1813 року повернулися до Австрії.", "bf1e49a8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Повернення Дум'ята від французів — залишення фортеці Лесбе", "06b1e7b0"], "d": ["До Дум'ята послали загін під проводом Ібрагім-паші з армії великого візира. Вранці 14 травня, коли готували штурм фортеці Лесбе, яка захищала Дум'ят, виявилося, що французи залишили фортецю, а гарнізон відійшов; узяли також два залежні від неї малі форти. Дум'ят став другим містом у гирлах Нілу, яке вийшло з-під французького контролю, — після Розетти, що впала у квітні.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Прийняття Каїра від французів — капітуляція Бельяра", "7a11bb5e"], "d": ["Під час спільної операції османських і британських сил у Єгипті командувач французьких сил у Каїрі генерал Бельяр підписав капітуляцію. Разом із Каїром з-під французького контролю вийшов і Суец, захоплений французами в листопаді 1798 року. Завершення окупації відбудеться через два місяці в Александрії, а евакуація з країни триватиме до жовтня.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Прийняття Александрії від французів — капітуляція Мену", "cd50663c"], "d": ["Головнокомандувача Східної армії генерала Мену 17 серпня обложили в Александрії; 21 серпня британці взяли форт Марабу поблизу міста, а 31 серпня Мену підписав капітуляцію армії. Повернення французьких частин до Франції почалося 2 вересня. Так окупація, що почалася висадкою в Александрії в червні 1798 року, закінчилася в тому самому місті, де почалася.", "22e807c1"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Висунення Польщею дніпровського рубежу — заснування Кременчука", "1bc86966"], "d": ["Річ Посполита заснувала нове прикордонне містечко біля вузлової переправи на середньому Дніпрі, якою проходили кримські набіги; через двадцять п'ять років тут з'явилася й фортеця. Так лінія польського контролю опустилася до північного краю запорозького степу, а ця переправа через річку вперше опинилася під постійною залогою якоїсь держави. У наступному столітті містечко як козацький полковий центр увійшло до устрою Гетьманщини.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Поява Умані на польському єдисанському прикордонному рубежі", "2e6551ab"], "d": ["Умань уперше згадано в документах як поселення на південно-східному краю Брацлавщини під польським управлінням. Вона лежала на шляхах набігів Кримського ханства на північ; те, що тут утвердилося постійне містечко, свідчить, що смуга порожнього степу між двома державами почала звужуватися з півночі. Наступні два століття місто залишалося найпівденнішим великим польським поселенням на цьому рубежі.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Висунення московської степової оборонної лінії — Чугуїв", "c68d36d3"], "d": ["Козацький ватажок Яків Острянин, який після повстання в Речі Посполитій знайшов притулок у Московському царстві, разом зі своїми людьми заснував прикордонне поселення над Донцем. Це був один із перших великих стрибків у степ оборонної лінії, яку Москва будувала проти кримських набігів; протягом наступного півстоліття на тій самій лінії одне за одним виникли такі міста, як Суми, Ізюм і Бахмут. Поселення проіснувало як сотенний центр Харківського полку до 1765 р.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Заснування Слобідської України — Суми та смуга степових поселень", "ab7abf59"], "d": ["Селяни й козаки з Білоцерківського полку на Правобережній Україні під проводом полковника Герасима Кондратьєва заснували нове містечко над Пслом; через чотири роки московський воєвода укріпив фортецю. Ця переселенська хвиля стала початком устрою Слобідської України, що відкрив для заселення порожній степ на південному кордоні Московського царства: прибульцям надавали звільнення від податків, а натомість очікували від них прикордонної сторожової служби. З 1658 до 1765 р. Суми були центром полку, що носив їхню назву.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Будівництво Єнікале — замикання Керченської протоки", "d9067015"], "d": ["Після передання Азова Росії 1700 р. єдині ворота з Чорного моря в Азовське стали стратегічною прикордонною лінією. Османська держава звела нове укріплення в місцевості Акинти-Бурну за десять кілометрів на північний схід від міста Керч і взяла прохід протокою під гарматний обстріл; фортеця дістала назву Єнікале, що саме й означає «нова фортеця». Фортеця сімдесят років залишалася східним замком Криму, а за дев'ятнадцятою статтею Кючук-Кайнарджійського договору 1774 р. разом із Керчю була поступлена Росії.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Фортеця Святої Єлизавети — південний кордон Росії впритул до османсько-кримської лінії набігів", "b9097272"], "d": ["Росія збудувала на землях запорозьких козаків нову фортецю, названу на честь святої Єлизавети. Відкрито заявленою метою фортеці було захистити балканських переселенців, оселених у Новій Сербії, від османських і кримських набігів; тобто російська прикордонна лінія вперше опустилася в середину степу, прямо на шляхи набігів. Цей передовий форпост став вихідною точкою розширення в Північному Причорномор'ї, яке почалося через двадцять років із Кючук-Кайнарджійським миром.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["II Ерзурумський договір — кордон по Шатт-ель-Арабу та поступка узбережжям Хузестану", "5d1f9103"], "d": ["Османсько-іранську прикордонну суперечку, яку не вдавалося розв'язати понад століття, врегулювали другим договором, підписаним в Ерзурумі після тривалих переговорів за посередництва Англії та Росії. Увесь водний шлях Шатт-ель-Араб залишився за османами; натомість поселення на східному березі річки — зокрема порт Мохаммера та острів Абадан навпроти нього — відійшли Каджарам. Так прибережна смуга Хузестану, що вважалася під османським управлінням від приєднання Басри 1546 р., через триста років була втрачена. Мехмед Хуршид-паша, член прикордонної комісії, створеної для визначення на місцевості проведеної договором лінії, у 1848-1852 рр. об'їздив край і написав «Сеяхатнаме-і Худуд».", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Відхід із Тебріза — кінець тижневої окупації та повернення через Карс і Байбурт", "fd1542e3"], "d": ["Султан Селім Явуз, який 6 вересня після перемоги під Чалдираном увійшов до Тебріза, пробув у місті близько тижня; скарбницю шаха Ісмаїла та частину міських митців і вчених разом із родинами він переселив до Стамбула. Він хотів перезимувати в Карабаху й наступного року продовжити похід, але через спротив яничарів відмовився від цього задуму, і військо повернулося через Карс і Байбурт. Отже, Тебріз не залишився в руках османів: Чалдиран був перемогою в польовій битві, а тривалі територіальні здобутки принесли наступного року похід на Кемах, Діярбакир і Східну Анатолію.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Приєднання Нусайбіна, Деріка та Сілопі до Османської держави — південне крило Діярбакира", "c3621d22"], "d": ["Після того як було прийнято здачу Аміда та засновано Діярбакирське бейлербейство, а Ідріс Бітлісі привернув на османський бік курдських беїв краю, під османське управління перейшли також Нусайбін, Дерік і Сілопі на південь від Мардинської рівнини. Ці місця організували як центри нахіє та каза нового бейлербейства; деякі, як-от Джизре, залишили місцевим беям зі статусом юрдлук-оджаклик (спадкового володіння). Так східноанатолійський похід, розпочатий після Чалдирана, досяг Верхньої Джезіри.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Проголошення незалежності Чехословаччини — перша держава-наступниця габсбурзької спадщини", "8f40155f"], "d": ["Коли Австро-Угорщина втратила сили у війні, а в країні тривали страйки, демонстрації та повстання, Національний комітет 28 жовтня 1918 р. проголосив незалежність Чехословаччини. На основі результатів виборів 1911 р. було створено тимчасові національні збори, а 14 листопада 1918 р. до виконання обов'язків став уряд, очільником якого було поставлено Масарика. Своє місце в міжнародному праві нова держава здобула за Сен-Жерменським договором (10 вересня 1919). На карті Чехословаччина з'являється 11 листопада 1918 р.; незалежність проголошено на два тижні раніше. Із цим проголошенням Градець-Кралове (Богемія), Оломоуць і Брно (Моравія) перейшли до Чехословаччини.", "74de11eb"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Проголошення Держави словенців, хорватів і сербів — хорватський Сабор розірвав зв'язки з Габсбургами", "2e5ae559"], "d": ["29 жовтня 1918 р. хорватський Сабор проголосив, що Хорватія, Славонія та Далмація розривають усі державно-правові зв'язки з Австро-Угорщиною; того ж дня в Любляні святкували утворення Держави словенців, хорватів і сербів. У Боснії та Герцеговині австро-угорська адміністрація 1 листопада 1918 р. передала повноваження уряду Народного віча. Ця держава проіснувала до проголошення в Белграді 1 грудня 1918 р. Королівства сербів, хорватів і словенців.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Заснування Австрійської Республіки — німецьке ядро габсбурзької спадщини", "1ec8b06f"], "d": ["Після того як 29 жовтня в Празі було проголошено створення Чехословаччини, а в Загребі — Держави сербів, хорватів і словенців, австрійські німці 30 жовтня також заснували Австрійську Республіку. Того ж дня Османська держава підписувала Мудроське перемир'я; кінець двох імперій опинився в календарі поруч.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Революція айстр — Карої став прем'єр-міністром, монархія в Угорщині почала розпадатися (народну республіку проголошено 16 листопада)", "d7780d2e"], "d": ["Коли стала очевидною поразка Центральних держав, в Угорщині посилилися антимонархічні настрої та стався зсув уліво. 31 жовтня 1918 р. внаслідок «революції айстр» прем'єр-міністром став граф Міхай Карої, який дотримувався радикальних поглядів, а згодом було проголошено народну республіку; 11 січня 1919 р. Карої обрано повноправним президентом.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Перемир'я у Вілла-Джусті — Австро-Угорщина склала зброю, Тренто і Трієст перейшли до Італії", "75da65fb"], "d": ["Підписання імператором Карлом 3 листопада 1918 р. перемир'я з італійцями у Вілла-Джусті прискорило розпад імперії. TDV прямо фіксує цей день як складання Австрією зброї: «Визнавши поразку, Австрія склала зброю 3 листопада, а Німеччина — 11 листопада». На карті цього дня Тренто і Трієст переходять від Австрії до Італії — це перша видима на карті передача території в ході розпаду. За цим перемир'ям Бриксен, Кортіна-д'Ампеццо, Ґьорц (Гориція) і Градиска на південь від лінії Бреннер — Тоблах — Юлійські Альпи перейшли під італійську окупацію.", "11a74dbf"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Незалежність Польщі — Регентська рада передала командування армією Пілсудському", "e8b546cf"], "d": ["Юзеф Пілсудський повернувся до Варшави 10 листопада 1918 р. 11 листопада Регентська рада передала йому командування армією, а за кілька днів доручила й сформувати національний уряд.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["Сербська армія окупувала Печ (тур. Печуй) — почалася сербська окупація Барані", "68f0695f"], "d": ["Печ, який мав стратегічне значення через вугільні копальні, 14 листопада 1918 р. опинився під сербською окупацією. Сербська окупація Печа та комітату Бараня тривала до серпня 1921 р.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["Сербська армія окупувала Тімішоару (Темешвар) — почалася сербська військова адміністрація в Банаті", "3cc85350"], "d": ["14 листопада 1918 р. сербські загони зайняли Тімішоару, розпустили національну гвардію та взяли на себе військове, а невдовзі й цивільне управління Банатом. На початку грудня до міста увійшли також французькі загони; румунську адміністрацію вдалося встановити лише в липні-серпні 1919 р.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Сербські загони увійшли до Сіґетвара — окупація південного Шомодя", "a06b1907"], "d": ["У ніч з 18 на 19 число 220 солдатів сербської армії під командуванням Обрена Петровича, яка просувалася на північ від лінії, визначеної Белградською військовою конвенцією, увійшли до Сіґетвара, центру повіту в Шомоді; цими силами утримувалися й села повіту. Окупація тривала до серпня 1921 р.; за Тріаноном Сіґетвар залишився в Угорщині.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Заснування Королівства сербів, хорватів і словенців та Великої Румунії — один день, дві держави", "6fd85345"], "d": ["Унаслідок об'єднання з Сербією слов'ян, які відокремилися від імперії після розпаду Австро-Угорщини, 1 грудня 1918 р. було засновано Королівство сербів, хорватів і словенців; приблизно 250,000 км² території та 12,000,000 населення. Його підвалини заклала Корфська декларація 20 липня 1917 р., а рішення про приєднання ухвалили збори в Подгориці 26 жовтня, у Боснії та Герцеговині 28 жовтня та в Новому Саді 25 листопада. Того ж дня внаслідок приєднання Трансильванії, Буковини та Бессарабії за рішенням їхнього населення постала Велика Румунія. На карті землі Сербського королівства переходять до Югославії. Із заснуванням королівства всі землі Сербського королівства (Ніш, Скоп'є, Бітола, Охрид, Приштина, Призрен, Печ та ін.) перейшли до Королівства сербів, хорватів і словенців.", "4fd0ff67"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["Румунська армія увійшла до Брашова (Brassó) і була урочисто зустрінута", "4a917d27"], "d": ["Румунська армія увійшла до Брашова в грудні 1918 р.; румунська знать міста урочисто зустріла армію та генерала Бертело.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["Італійська армія окупувала Книн", "7949dd0f"], "d": ["Італійська армія окупувала Книн 19 грудня 1918 р. Окупація тривала до 4 квітня 1921 р., коли після Рапалльського договору італійська армія залишила місто.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Чехословацькі загони взяли Кошиці (Kassa)", "0989490f"], "d": ["Коли 29 грудня 1918 р. 30-й піхотний полк імені Алоїса Їрасека зайняв місто, Кошиці фактично приєдналися до Чехословацької Республіки.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["Румунська армія увійшла до Сату-Маре (Szatmár, 19 квітня) та Ораді (Варад, 20 квітня)", "3ee2bd72"], "d": ["У Великодню суботу 19 квітня 1919 р. в Сату-Маре місцева делегація на чолі з д-ром Іліє Каролом Барбулом зустріла на мосту через Сомеш перший роз'їзд 2-ї кавалерійської дивізії під командуванням полковника Ресселя. Наступного дня, 20 квітня 1919 р., румунські загони під командуванням генерала Траяна Мошою увійшли до Ораді.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Версальський договір — повернення Ельзасу-Лотарингії Франції закріплено юридично", "3babdfcb"], "d": ["Паризька мирна конференція зібралася 18 січня 1919 р., а 28 червня з Німеччиною було підписано Версальський договір. Стаття 51 договору повернула під суверенітет Франції Ельзас-Лотарингію (Страсбург, Мец, Кольмар, Мюлуз), яка з 1871 р. була німецькою, — але передачу прив'язала не до дня підписання, а заднім числом до перемир'я 11 листопада 1918 р. Та сама низка конференцій породила Сен-Жерменський договір з Австрією (10 вересня 1919), Нейїський з Болгарією (27 листопада 1919), Тріанонський з Угорщиною (4 червня 1920) та Севрський з Османською державою (10 серпня 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Румунські загони дісталися Лугожа (Lugos) — румунська адміністрація на сході Банату", "f65fc73c"], "d": ["Поїзд із румунськими загонами прибув до Лугожа 22 липня 1919 р. о 14-й годині; мешканці міста зустріли армію на вокзалі, префект Караш-Северіна Джордже Добрін виголосив вітальну промову, а генерал Жітіану відповів. У тій частині Банату, що дісталася Румунії, румунську адміністрацію встановлено в липні 1919 р.; юридична передача відбулася за Тріанонським договором 1920 р.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["Румунська армія увійшла до Тімішоари (Темешвар) — у місті встановлено румунську адміністрацію", "8728e1d1"], "d": ["До Тімішоари, куди 14 листопада 1918 р. увійшли сербські, а на початку грудня — французькі загони, вранці 3 серпня 1919 р. увійшли перші підрозділи румунської армії під командуванням полковника Вірджіла Економу, і в місті встановили румунську адміністрацію.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["Армія КСХС увійшла в Прекмур'я — Мурська-Собота та Лендава вийшли з-під угорської адміністрації", "21b2ba08"], "d": ["12 серпня 1919 р. загони Королівства сербів, хорватів і словенців увійшли в Прекмур'я за річкою Мурою; того дня угорська адміністрація в краї припинилася. Юридична передача відбулася за Тріанонським договором 1920 р.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Сен-Жерменський договір — зменшення Австрії закріплено юридично", "e7b722d5"], "d": ["Після війни Австрія підписала із союзниками Сен-Жерменський мирний договір. За договором Австрія визнавала незалежність Угорщини, Чехословаччини та Югославії; погоджувалася не об'єднуватися з Німеччиною без згоди Ліги Націй, скасувати загальну військову повинність та обмежити армію 30,000 осіб. Саме за цим документом Чехословаччина здобула своє місце в міжнародному праві. Передача територій на карті відбулася роком раніше; цей договір її зафіксував. За цим договором Львів, Яблунків, Карвіна, а також далматинське узбережжя та острови (Крк, Црес, Лошинь, Раб, Паг, Хвар, Корчула, Віс, Задар, Шибеник, Книн) перейшли від Австрії в розпорядження Головних союзних держав; Ужгород і Мукачево (Підкарпатська Русь) — до Чехословаччини.", "b4d5f306"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Нейїський договір — Болгарія втратила Західну Фракію та егейське узбережжя", "01f2b8c8"], "d": ["Коли війна закінчилася поразкою, цар Фердинанд був змушений просити перемир'я та зректися престолу на користь сина Бориса (29 вересня 1918). За Нейїським договором, який завершив війну, Болгарія зазнала стратегічних територіальних втрат на користь сербів, втратила всю Західну Фракію, мусила поступитися Греції узбережжям Егейського моря та підтвердила положення Бухарестського договору, за яким Південна Добруджа відходила Румунії. На карті ця передача відображена не в день договору, а в травні 1920 р., коли фактично змінилася влада: Дедеагач, Софулу, Орестіада та Чирмен переходять до Греції 14 травня, а Гюмюльджіне, Ксанті, Дідімотіхон і Феррес — 27 травня.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Тріанонський договір — Угорщина втратила дві третини своєї території", "84aff507"], "d": ["За Тріанонським договором, підписаним через три місяці після того, як 1 березня 1920 р. Горті став регентом королівства, Угорщина зазнала тяжких територіальних і людських втрат: за межами кордонів опинилися дві третини з 283,000 км² її території без урахування Хорватії та шістдесят відсотків населення, зокрема понад три мільйони угорців, а армію скоротили до 35,000 осіб. На карті Угорське регентство показано в цих зменшених межах; Трансильванія та Верхня Угорщина також саме цього дня набувають кольорів Румунії та Чехословаччини. За цим договором Братислава, Кошиці, Нітра та Комаром (Верхня Угорщина) юридично перейшли до Чехословаччини; Орадя, Сату-Маре, Лугож, Алба-Юлія та Брашов (Трансильванія та схід Банату) — до Румунії; Суботиця, Бечкерек, Бач, Мурська-Собота та Чаковець (Бачка, захід Банату, Прекмур'я, Меджимур'я) — до Королівства сербів, хорватів і словенців.", "f7c54f07"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["Банат розділено, Темешвар залишено Румунії (Тріанон, ст. 27/3 і 45)", "256b4aca"], "d": ["Тріанонський договір провів угорсько-румунський кордон статтею 27/3, а статтею 45 Угорщина відмовилася на користь Румунії від усіх прав і титулів на колишні землі монархії по той бік цього кордону; так об'єднання Трансильванії, Банату, Крішани та Марамуреша з Румунією було визнано в міжнародному праві. Область Банат розділили між Румунією та Сербією; місто Тімішоара (Темешвар) приєдналося до Румунського королівства. Румунська адміністрація в Темешварі фактично діяла з 3 серпня 1919 р.; договір закріпив це становище юридично.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["Італійська армія залишила Книн", "a1d2e846"], "d": ["Після Рапалльського договору італійська армія 4 квітня 1921 р. залишила Книн; окупація, що почалася 19 грудня 1918 р., завершилася.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Італія передала Шибеник Королівству СХС", "9d07b12a"], "d": ["Італійська окупація, що почалася 6 листопада 1918 р., завершилася 12 червня 1921 р. церемонією за участю військових представників Італії та Королівства СХС.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Сербські загони залишили Сіґетвар — місто перейняла угорська жандармерія", "97781b77"], "d": ["Після набуття чинності Тріанонським договором сербські війська 17 серпня почали відходити з Барча та Сіґетвара й вивезли все, що можна було перевезти. 20 серпня близько полудня увійшли загони угорської жандармерії; по обіді міська рада та службовці склали присягу, а о п'ятій годині в ратуші відбулася військова передача влади.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["Сербська окупація Печа (тур. Печуй) завершилася — Угорська національна армія увійшла в місто", "f437115a"], "d": ["18 серпня 1921 р. сербські загони почали залишати край; 20-21 серпня управління містом і комітатом передали представникам угорського уряду, а 22 серпня в місто увійшли підрозділи Угорської національної армії.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["Австрійський бундесгеєр увійшов у Бургенланд — територію, залишену Тріаноном Австрії, фактично перебрано", "7bfd6915"], "d": ["Тріанонський (1920) і Сен-Жерменський (1919) договори залишили Австрії німецькомовну смугу Західної Угорщини; перша спроба перебрати її 28 серпня 1921 р. провалилася через опір угорських іррегулярних загонів. Після Венеційського протоколу (13 жовтня 1921) Генеральна комісія союзників 11 листопада схвалила вступ бундесгеєру, і через два дні почалося перебирання північного Бургенланду; південь перейняли 6 грудня 1921 р., а область Шопрона за підсумками плебісциту залишилася в Угорщині.", "c78d0f81"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["Племена околиць Таїфа потрапили під ваххабітський вплив — Тураба та Хурма відірвалися від Мекканського шерифату", "d3b644be"], "d": ["Племена околиць Таїфа, підлеглі мекканському шерифу Галібу, 1801 року потрапили під ваххабітський вплив; емір Дірії передав їх під управління бедуїнського шейха Усмана аль-Мудаїфі, зятя шерифа (чоловіка сестри) та його ворога. Східні оази Тураба та Хурма на цій хвилі також перейшли на бік Саудитів. Це стало передвістям того, як ваххабіти в лютому 1803 року взяли Таїф, а потім і Мекку.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["Єгипетські гарнізони відійшли з Тураби, Біші та Раньї на півдні Хіджазу", "72b87aa1"], "d": ["У місяці після того, як Тосун-паша уклав мир з ваххабітами й у листопаді 1815 року повернувся до Каїра, на півдні Хіджазу почалися заворушення; гарнізони Мехмеда Алі-паші з Кавали мусили відступити з Біші, Раньї та Тураби. Від'їзд Ібрагім-паші з Каїра в серпні 1816 року в новий похід відбувся вже після цього відступу. Хто правив Турабою до падіння Дірії (1818), у джерелі не вказано.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["Єгипетський гарнізон відійшов із Сулейманії в Харджі й дістався Манфухи — південь Неджду залишився без проводу", "2743f70d"], "d": ["Єгипетський пост, який Ібрагім-паша після зруйнування Дірії розмістив у Сулейманії в Харджі, перш ніж вирушити за наказом паші про відхід, убив на бенкеті чотирьох шейхів Ділама й був обложений бедуїнами. Визволений гарнізон 13 серпня 1819 року дістався Манфухи, і почався марш на Касим. На півдні Неджду не залишилося центральної влади; спроби родини Саудів не давали результату до 1824 року.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Шехіркьой повернувся під османську владу — смерть Джураджа Бранковича", "e37156d1"], "d": ["Шехіркьой, який 1443 року захопила армія хрестоносців і який після Едірнесько-Сегедського договору 1444 року Мурад II залишив сербам, 1456 року зі смертю сербського деспота Джураджа Бранковича повернувся під османську владу. Того ж року й з тієї самої причини під османське управління остаточно перейшов і Ніш; так лінію долини Нішави, що виходить на софійський шлях, було завершено. Договір підписали на десятирічний строк, а після Варни (1444) і Другої Косовської битви (1448) деспотовина проіснувала лише стільки, скільки жив Бранкович.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Султан Селім Явуз вирушив з Едірне в чалдиранський похід", "1f7921f7"], "d": ["Султан Селім Явуз, залишивши свого сина шехзаде Сулеймана, який був у Манісі, своїм заступником у Стамбулі, вирушив з Едірне в похід проти держави Сефевідів. Військо мало пройти Анатолією по лінії Сівас—Ерзінджан—Ерзурум і наприкінці серпня зустрітися під Чалдираном із силами шаха Ісмаїла.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Кизикермен (Газі-Керман) і правий берег Дніпра перейшли під безпосередній османський контроль", "56a28224"], "d": ["Фортеця Кизикермен і правий берег Дніпра, які Кримське ханство утримувало з середини XV століття, тоді перейшли під безпосередній контроль Османської держави; фортеця перетворилася на османський передовий пост на північному краю степу. На відміну від земель Кримського ханства довкола Бахчисарая та Ор-Капи, Кизикерменом управляли безпосередньо османи.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Прозоровський окупував Ор-Капи — російські сили залишалися в Перекопі до анексії", "afdfe804"], "d": ["Коли генерал Прозоровський, який ішов, щоб посадити на кримський престол Шагін Ґерая, дійшов до Перекопської лінії, Девлет Ґерай, каймакам і татари вже покинули місто; Прозоровський без бою окупував фортецю Ор і Перекопську лінію. Росіяни осіли в Ор-Капи й залишалися там до анексії Криму 1783 року.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Окупація Анапи росіянами (третя облога)", "e6a7d6d5"], "d": ["Фортецю Анапа, збудовану 1781 року за управління Ферах Алі-паші, під час війни росіяни тричі брали в облогу; наприкінці третьої облоги, 26 липня 1791 року, її окупували. Окупація була тимчасовою — оскільки за Ясським договором (1792) на Кавказі визнали старі кордони, фортецю повернули Османській державі.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Здача Анапи росіянам Осман-пашею", "3ccbdd1d"], "d": ["На початковому етапі османсько-російської війни 1828-29 років Анапу взяли в облогу, і 24 червня 1828 року османські сили у фортеці під проводом Осман-паші здалися росіянам. Цього разу здача виявилася остаточною: за Адріанопольським (Едірнеським) договором, підписаним наступного року (14 вересня 1829 року), Анапа та Кавказ офіційно вийшли з-під османської влади.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Тургут-реїс став бейлербеєм Триполітанії — провінція розширилася на схід до Тобрука та Дерни", "160fa43c"], "d": ["Після завоювання Триполі 1551 року Тургут-реїс у джумада аль-уля 963 року (березень 1556 року) прибув до Триполі з титулом бейлербея. За дев'ять років намісництва він працював над облаштуванням та укріпленням провінції, поширив османське управління на південь аж до Феццану та, розширивши кордони на схід, узяв Тобрук і Дерну на узбережжі Барки. Так еялет Триполітанія охопив прибережну смугу аж до єгипетського кордону.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Московське царство взяло Астрахань — Нижнє Поволжя перейшло під російський контроль", "d02abd83"], "d": ["1556 року Московське царство, взявши й Астрахань, зробило, за висловом TDV, «крок, що матиме вельми важливі наслідки в майбутньому»; з окупацією Астраханського ханства Нижнє Поволжя перейшло під російський контроль. Кримський хан Девлет Ґерай хотів запобігти цим захопленням, але не зумів. 1569 року османи відповіли на ці події астраханським походом; проте, не досягнувши успіху у встановленні контролю над Нижнім Поволжям, залишили боротьбу з Московським царством кримському ханові.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Завоювання Костайниці та Нови — дві фортеці лінії Уни", "2093e452"], "d": ["Костайницю, яку влітку 1556 року обложив Малкоч-бей, обороняв капітан Панкраціє Лустгаллер із понад 60 солдатами; фортецю здали вже через день після початку облоги, 16 липня, і Лустгаллера звинуватили в тому, що він її продав. Невдовзі взяли й спалили також Нові; так дві найважливіші фортеці на Уні одним ударом перейшли до рук османів. Того ж року у Відні заснували Придворну воєнну раду (гофкрігсрат), яка мала з центру керувати прикордонною обороною.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Маку перейшов до османів — Махмуді Іваз-бею доручено збудувати фортецю", "5932ad38"], "d": ["1574 року Османська держава доручила вождеві курдського племені махмуді Іваз-бею відібрати Маку в іранців і збудувати там фортецю. Ця фортеця на східному краю Ванського еялету посіла важливе місце в подіях, що відбувалися в краї за османського періоду.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Випущено перші османські паперові гроші (каїме)", "d2e5e192"], "d": ["У перші роки Танзімату, під час пошуку доходів для скарбниці, за пропозицією Аріфа Хікмет-бея, майбутнього шейх-уль-іслама, було ухвалено випуск каїме — вдосконаленої форми системи есхамів. Перші каїме на загальну суму 160 000 лір (32 000 кесе) через нагальну потребу в грошах, не чекаючи друку, випустили написаними від руки за міністра фінансів Саїб-паші, ймовірно, у червні 1840 року. Ці папери, що мали силу готівки, мали перебувати в обігу вісім років і приносити 12,5% річних; забезпечення вони не мали, лише проценти за ними забезпечувалися доходом стамбульської митниці. Населення, не звикле до таких грошей, не сприйняло їх прихильно, а рукописні каїме невдовзі стали мішенню фальшивомонетників.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Узяття Малакки португальцями", "e1556746"], "d": ["Малакка, заснована в 1390-х роках, стала найжвавішим у краї портом морської торгівлі між Китаєм, Індією та Заходом і, як центр Малаккського султанату, головним осередком поширення ісламу на навколишні острови. Португалець Афонсу де Албукерке захопив місто 10 серпня 1511 року; місто пограбували, а його мечеті, династичні гробниці та інші кам'яні будівлі зруйнували, щоб використати каміння для будівництва фортеці. Під португальським управлінням Малакка не змогла зберегти колишню торговельну першість; мусульманські купці звернулися до порту султанату Ачех на Суматрі. Через напади португальців, які оселилися в Малакці, на Ачех султан Ачеху Алаеддін Ріаят-шах 1565 року попросив допомоги в султана Сулеймана Законодавця.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Правитель Луристану Шахверді заявив про вірність шаху Аббасу", "85791f94"], "d": ["Правитель Луристану Шахверді, який 1589 року, підкорившись османам, став залежним від багдадського бейлербея, за розповіддю сефевідського історика Іскандер-бега Мунші, 1000 (1591-92) року був змушений заявити про вірність сефевідській короні. Те саме джерело пише, що в ці роки він хитався між двома сторонами, турбував намісників Хамадана та робив набіги на Боруджерд, а 1002 (1593-94) року шах Аббас окупував Хорремабад і призначив у місто намісника. Енциклопедія ісламу TDV натомість датує повне приєднання до Сефевідів Луристану, який за Стамбульським договором 1590 року перейшов під османське управління, 1603 роком. Дві традиції подають різні дати; цей запис показує заяву про вірність за сефевідською традицією, а запис 1603 року — остаточну втрату. На карті з цим записом власник не змінюється: до 1603 року Луристан показано на османському боці.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Остаточний перехід Луристану до Сефевідів", "4c5cf67b"], "d": ["Луристан, який за Стамбульським договором (Ферхад-паші) 1590 року перейшов під османське управління, шах Аббас I 1603 року повністю приєднав до Сефевідів. Проте сефевідський історик Іскандер-бег Мунші пише, що шах Аббас окупував Хорремабад раніше, 1002 (1593-94) року, і призначив у місто сефевідського намісника; ця розбіжність між двома традиціями не розв'язана. Того ж року до рук шаха Аббаса перейшла й османська фортеця Нехавенд на північ від Луристану; намісник Хамадана Хасан-хан зрівняв фортецю із землею.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["Каталонська компанія вступила на візантійську службу — початок анатолійського походу", "6623e7db"], "d": ["Візантійська імперія, втрачаючи землі в Західній Анатолії під натиском тюркських бейліків, узяла на службу як найманців каталонський загін чисельністю близько 6500 осіб під проводом Рожера де Флора. Згідно зі статтею TDV про Візантію, загін 1303 року прийшов на допомогу імперії, а наступного року визволив Алашехір, обложений Ґерміянідами. Проте невдовзі компанія почала грабувати місцевості, через які проходила; Візантія переправила її до Фракії та 1305 року наказала вбити Рожера де Флора.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["Правитель Хадрамауту та Шихра визнав османську владу — повернення Хадима Сулейман-паші з індійського походу", "b5cb9363"], "d": ["Хадим Сулейман-паша, повертаючись з облоги Діу, 27 листопада 1538 року зайшов у порт Шихр; коли правитель Хадрамауту та Шихра прийняв османську владу, паша вирушив до Адена. Хадрамаут було організовано як санджак, підпорядкований Ємену, але управління в регіоні й далі утримували вожді племені Катірі. Ця залежність тривала до відходу османів з Ємену 1635 року.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Мегрельське (Дадіані) князівство залишено в османській сфері впливу", "ea54e8ea"], "d": ["За положеннями Амасійського договору, що ділили Грузію, князівство Дадіані (Мегрелія та Сванетія) в Західній Грузії разом з Імереті та Гурією залишили в османській сфері впливу. На карті центр Мегрелії Зугдіді від цього дня показано як князівство, підвладне османам; фактичну ж заяву про покору буде зроблено 1578 року.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Ахалцихське атабекство перейшло під османське управління — Алтункале, Хиртис і Ахалкалакі", "024bb326"], "d": ["Одразу після того, як Лала Мустафа-паша розбив під Чилдиром сефевідський авангард, під османське управління перейшли й землі, що були в руках грузинських атабеків. Дедіс Імеді, який тримав Алтункале з околицями, та його сини заявили про покору; санджакбей Ардагана взяв Чилдир і Тюмюк, а інші османські частини — Хиртис і Ахалкалакі. Менучехру та його братові залишили по санджаку, а решту країни атабеків підпорядкували безпосередньому управлінню. Відтоді Ахалцихе стане центром новоутвореного Чилдирського еялету; Менучехра, який приїхав до Стамбула, став мусульманином і прийняв ім'я Мустафа, 1 липня 1579 року поставлять на чолі цього еялету.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Килич Алі-паша збудував фортецю Фаш (Поті) — османська база в гирлі Ріоні", "f729ba95"], "d": ["Капудан-паша Килич Алі-паша 26 липня 1579 року збудував фортецю Фаш там, де річка Ріоні (Фаш) впадає в Чорне море.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Створено Горійську провінцію — пряме османське правління на заході Картлі", "9a7c8bc5"], "d": ["1578 року грузинські князі округів Горі та Мухрані підкорилися османам. 1587 року на заході Картлі було створено Горійську провінцію, а регіон перейшов під пряме османське управління. Фортецю Горі, втрачену під час повстання грузина Сімона, було повернено 1601 року; османське правління завершилося 1603 року з походом шаха Аббаса.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Набіги Міхая Хороброго на дунайські фортеці — Русе спалено, Бреїлу взято, Сілістру пограбовано", "d0b83f6a"], "d": ["Волоський воєвода Міхай Хоробрий, який приєднався до Священної ліги, взимку 1594-95 років ударив по фортецях і містах на Дунаї, що перебували під безпосереднім османським управлінням. Згідно зі статтею TDV про Русе, в лютому 1595 року, хоч і не зумівши взяти фортецю, він захопив і спалив місто. За статтею про Бреїлу, він захопив Бреїлу на лівому березі Дунаю, і місто залишалося в його руках до 1601 року; стаття про Мурада III також пише, що волоське військо спалило бреїльську фортецю й дійшло аж до Сілістри. За згаданим у статті про Сілістру записом перепису, навесні 1595 року волоське військо перейшло Дунай і пограбувало Сілістру; фортецю міста зруйнували, і нею довго не можна було користуватися. Того ж літа Коджа Сінан-паша вирушив у похід на Волощину.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Шах Аббас повернув Тбілісі — кінець османського правління в Картлі та Кахетії", "a6995ea8"], "d": ["1603 року шах Аббас I відбив у османів Тбілісі та проголосив Картлі ханством; у Кахетії також установилося сефевідське правління. Так завершилося османське правління у Східній Грузії, започатковане 1578 року походом Лали Мустафа-паші; Тбілісі знову перейшов до рук османів лише 1723 року.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Фортецю Фаш (Поті) зруйнували війська Імеретії, Гурії та Мегрелії", "3c3d4ed7"], "d": ["1640 року фортецю Фаш зрівняли із землею війська Імеретії, до яких приєдналися князі Гурії та Мегрелії. Османська присутність у гирлі Ріоні перервалася, доки 1724 року фортецю не відбудували.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Почався Прутський похід — під час османсько-російської війни 1710-1711 років військо вийшло зі Стамбула", "3161364b"], "d": ["Напад Росії на османські землі, недотримання царем Петром положень Стамбульського договору 1700 року та підбурювання кримського хана Девлет Ґерая спонукали Ахмеда III оголосити війну Росії. Згідно зі статтею TDV про Ахмеда III, ця війна, яку згодом називатимуть Прутським походом, фактично почалася з виступу османського війська зі Стамбула 9 квітня 1711 року. Військо під проводом Балтаджі Мехмед-паші, об'єднавшись із кримськими силами, рушило до річки Прут; похід у липні завершиться тим, що російську армію затиснуть на березі Прута.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Почалася відбудова фортеці Фаш (Поті)", "0afbc4b0"], "d": ["За рішенням, ухваленим 23 грудня 1723 року, у березні 1724 року почалася відбудова зруйнованої фортеці Фаш; будівництво завершили 1729 року.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["Хой, Капан і область Карадаг знову перейшли під османське управління", "c52c94d1"], "d": ["Під час іранського походу, розпочатого 1723 року, Хой разом із Капаном та областю Карадаг 6 травня 1724 року знову перейшов під османське управління, а 1728 року був занесений до османського податкового перепису. Атлас вважає, що й Котур, розташований за 40 км на південний захід від Хоя, того самого дня перейшов від Сефевідів до османів (ланцюжок перейнято від Хоя: Uluerler 2015, Turkish Studies 10/5, с. 6; окремої дати для Котура в джерелі немає — задеклароване наближення).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Надір увійшов у Шемаху — центр Ширвану вийшов з-під османської влади", "778a4988"], "d": ["17 серпня 1733 року Надір увійшов у Шемаху, яка за Стамбульським договором від 24 червня 1724 року разом із центральною частиною Ширвану відійшла до османської частки. Після цього османське правління на Кавказі швидко розпалося; 1735 року було втрачено Гянджу та Тбілісі.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ультиматум російському посланнику — останній крок до османсько-російської війни 1787-1792 років", "cb389693"], "d": ["Напруга, що тривала після анексії Криму Росією 1783 року, прорвалася, коли з'ясувалося, що російське консульство в Александрії підбурює мамлюцьких беїв у Єгипті проти османів. Згідно зі статтею TDV про Абдул-Гаміда I, реїсюлькюттаб Сулейман Фейзі-ефенді 27 липня 1787 року вручив російському посланнику в Стамбулі ультиматум із семи пунктів. Не чекаючи відповіді Росії, ухвалили рішення про війну й за кілька тижнів її оголосили; метою війни було повернення Криму.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Російські війська взяли фортецю Фаш (Поті) — гирло Ріоні втрачено", "c1241b5a"], "d": ["Під час російсько-турецької війни 1806–1812 років російський напад у травні 1809 року зазнав невдачі; проте 27 листопада 1809 року фортецю здали росіянам.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Згідно з Бухарестським миром фортецю Фаш (Поті) повернули османам", "6a3a8a0a"], "d": ["Згідно з Бухарестським миром 1812 року фортецю Фаш 19 грудня 1812 року передали Османській державі.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Фортеця Фаш (Поті) вдруге перейшла до росіян — за Адріанопольським миром залишилася за Росією", "682d58f0"], "d": ["На початку російсько-турецької війни 1828–1829 років, 26 червня 1828 року, фортецю Фаш здали росіянам. За Адріанопольським миром від 14 вересня 1829 року Поті разом з Ахалцихе, Ахалкалакі та Анапою відійшов до Росії.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Англійці окупували Насирію — Євфратський фронт", "669b979e"], "d": ["Британські сили, що наступали з Басри вздовж Євфрату, 24 липня 1915 року розбили османські частини й наступного дня окупували Насирію. Басра впала в листопаді 1914 року; Насирія ж залишалася в османських руках ще близько восьми місяців.", "bd125229"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Італійська окупація Антальї", "328331da"], "d": ["Після Мудроського перемир'я, коли держави Антанти розміщувалися в зонах окупації в Анатолії, Італія спрямувалася на південно-західну Анатолію. Згідно зі статтею TDV про Анталью, місто з околицями на підставі положень перемир'я 29 квітня 1919 року окупували італійці. Окупація тривала близько двох років.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Визволення Мараша — французи залишили місто", "a57d884e"], "d": ["Мараш, який британці окупували 22 лютого 1919 року, за угодою між двома державами 29 жовтня 1919 року передали французам. Поведінка вірмен у складі французьких частин і спуск турецького прапора на фортеці підняли населення на повстання; у місті організувалися Товариство захисту прав і Національні сили. Згідно зі статтею TDV про Кахраманмараш, наприкінці боїв 11 лютого 1920 року французи залишили місто й почали відходити в напрямку Ісляхіє, а 11-12 лютого Мараш було визволено. 1925 року місто нагородили медаллю Незалежності.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Визволення Урфи — французький гарнізон покинув місто", "c889488c"], "d": ["В Урфі, яку в березні 1919 року окупували британці, а приблизно через сім місяців — французи, населення 7 лютого 1920 року повстало проти окупаційних сил. Згідно зі статтею TDV про Шанлиурфу, після двомісячних боїв французи 10 квітня 1920 року погодилися залишити Урфу на умовах угоди й наступного дня вийшли з міста.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Почалася операція Східного фронту — Кязим Карабекір перейшов у наступ проти Вірменії", "151678df"], "d": ["Оскільки Севрський договір залишав Ерзурум, Трабзон, Ван, Бітліс і Бінгель Вірменії, а вірменські напади в краї посилювалися, уряд Великих національних зборів Туреччини 20 вересня 1920 року дозволив операцію. Згідно зі статтею TDV про Кязима Карабекіра, командувач Східного фронту Карабекір, наказавши своїм частинам, які тримали перевали гори Соганли, перейти в наступ, 28 вересня почав східну операцію. Узяли Сарикамиш, Ґьоле та Кагизман; через місяць операція продовжилася визволенням Карса.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Визволення Карса — Східний фронт увійшов у Карс", "4e578071"], "d": ["Згідно зі статтею TDV про Карс, 30 жовтня 1920 року Кязим Карабекір-паша увійшов у Карс, і місто визволили з-під вірменського управління, якому британці 1919 року залишили контроль. Стаття про Карабекіра підкреслює, що це було друге визволення Карса: уперше місто відібрали у вірмен у квітні 1918 року. Просуваючись, Східний фронт 7 листопада взяв Гюмрі; війна закінчилася Александропольським (Гюмрійським) договором 3 грудня 1920 року.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Узяття Гюмрі — Східний фронт просунувся вглиб Вірменії", "cfddf791"], "d": ["Частини Кязима Карабекір-паші, які продовжували операцію після визволення Карса, 7 листопада 1920 року взяли Гюмрі. Переговори з вірменами, які погодилися на перемир'я, велися в Гюмрі, і війна закінчилася Александропольським (Гюмрійським) договором, підписаним 3 грудня 1920 року.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Взяття Игдира", "6e952d2e"], "d": ["Через п'ять днів після взяття Гюмрі, 12 листопада 1920 року, Східний фронт узяв також Игдир. За Гюмрійським договором від 3 грудня 1920 року Игдир було залишено Туреччині.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Кінець оборони Антепа — місто після десятимісячного опору залишили французам", "e080af8b"], "d": ["Антеп, у який 17 грудня 1918 року увійшли англійці, 5 листопада 1919 року було передано французам; першим опором на лінії Антеп — Кіліс керував Шахін-бей. За статтею TDV про Газіантеп, мешканці міста чинили опір французьким силам з 1 квітня 1920 року до 7 лютого 1921 року; коли опір було зламано, сили оборони відступили, а 9 лютого французи встановили контроль над містом. Великі національні збори Туреччини за три дні до того, 6 лютого 1921 року, надали місту, яке десять місяців протистояло окупації, звання «газі». Антеп мали евакуювати 25 грудня 1921 року після Анкарської угоди.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Визволення Ардагана та Артвіна", "b9e50d5e"], "d": ["Після Гюмрійського договору Східний фронт звернувся проти тієї частини Ельвіє-і Селясе (трьох санджаків), яка перебувала в руках Грузії. За статтею TDV про Ардаган, наприкінці боротьби з грузинськими та вірменськими загонами 23 лютого 1921 року разом з Артвіном було визволено й Ардаганський санджак. Стаття про Казима Карабекіра зазначає, що цим кроком було повернено землі трьох санджаків, за винятком каз Чюрюксу, Аджара та Батум.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Московський договір — ВНЗТ і Радянська Росія визначили східний кордон", "78d46573"], "d": ["16 березня 1921 року між урядом Великих національних зборів Туреччини та Радянською Росією було підписано Московський договір. За статтею TDV про Карс, унаслідок прикордонних постанов цього договору та Карського договору від 13 жовтня 1921 року Карс залишився в межах нової турецької держави. А за статтею про Ахалцихе, за цим договором Ахалцихе було приєднано до Тифліського вілаєту Грузинської Радянської Соціалістичної Республіки. Східний кордон остаточно визначив Карський договір, підписаний через сім місяців із республіками Південного Кавказу. За цим договором Батум і Аджару (Хуло, Сарпі, Мурванеті, Махалакаурі) було залишено Радянській Грузії.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Італійці почали евакуювати Анталію", "f7a4eaa7"], "d": ["За статтею TDV про Анталію, італійська окупація, що тривала з 29 квітня 1919 року, завершилася, коли 1 червня 1921 року італійці почали евакуювати місто. Таким чином Анталія та її околиці звільнилися від окупації, не чекаючи воєнного результату національно-визвольної боротьби.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Цетинський сейм — після Мохача хорватська знать обрала Габсбурга Фердинанда королем Хорватії", "55fc9d7e"], "d": ["Коли після загибелі під Мохачем угорсько-хорватського короля Людовіка II престол спорожнів, хорватська знать 31 грудня 1526 року зібралася в Цетині й у перший день нового року проголосила королем австрійського ерцгерцога Фердинанда. За формулюванням TDV, хорвати здійснили це обрання незалежно від угорської знаті; виборча грамота обґрунтовувала його тим, щоб перед лицем османських набігів не відірватися від християнської держави. Так хорватські фортеці, сусідні з османською Боснією, були приєднані до корони династії Габсбургів; за TDV, коли в 1530-х роках Габсбурги почали впорядковувати хорватське прикордоння, головним центром цієї лінії став Біхач.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Короткочасне османське правління в Біхачі — після Мохача та падіння Яйця", "fd4118fe"], "d": ["Після перемоги під Мохачем османи взяли в Боснії Яйце, центр угорської буферної зони, та Баню-Луку. За статтею TDV про Біхач, у рік після Мохача, по взятті фортеці Яйце, Біхач на короткий час знову перейшов під османське управління. Коли і як фортецю було втрачено, джерело не повідомляє; TDV лише зазначає, що в 1530-х роках, упорядковуючи хорватське прикордоння, Габсбурги зробили головним центром Біхач, який перебував у руках християн. Остаточне завоювання Біхача відбулося 1592 року внаслідок походу бейлербея Боснії Хасан-паші.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Кінець французького правління в Дубровнику — австрійські війська увійшли в місто, колишнього османського данника", "38d42444"], "d": ["За TDV, Дубровницькій республіці, яка з 1365 року перебувала під османським покровительством, поклали край французи, захопивши місто 27 травня 1806 року. Узимку 1813–1814 років мешканці міста повстали проти французів; 3 січня 1814 року австрійський генерал-майор Мілутинович, який прибув до Гружа з двома хорватськими батальйонами, взяв гарнізон в облогу; після чотириденного бомбардування французький гарнізон надіслав до генерала посланця. На світанку 28 січня австрійські та британські війська рушили з Гружа в місто; 31 січня в області почала діяти тимчасова австрійська адміністрація. Приєднання міста до австрійських земель остаточно закріпив Віденський конгрес 1815 року.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Проголошення Королівства Сербії — колишнє залежне від османів князівство стало королівством", "7d90e712"], "d": ["Князівство Сербія, яке здобуло незалежність 1878 року і того ж року відібрало в османів Ніш, за Мілана Обреновича було перетворене на королівство. Першою статтею закону, виданого в Белграді, князівство проголошувалося Королівством Сербія, а князь Мілан став королем під іменем Мілан I; закон того ж дня опублікували в офіційній газеті Srpske novine. Так Сербія, яка до 1878 року була залежним від османів князівством, посіла своє місце на Балканах із титулом королівства. Цим проголошенням усе Князівство Сербія (Белград, Ніш, Ягодина, Вране, Лесковац, Прокупле, Пірот та ін.) стало Королівством Сербія.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["У Палестині запроваджено британську цивільну мандатну адміністрацію — кінець військового управління на відібраних у османів землях", "c0d7b76a"], "d": ["Коли 1917 року генерал Алленбі взяв Газу, а потім Єрусалим, чотирьохсотлітнє османське панування в Палестині завершилося, а Єрусалим у 1917–1920 роках залишався під британською військовою адміністрацією. Конференція в Сан-Ремо 1920 року віддала Палестину під британський мандат; з липня 1920 року Британія запровадила в регіоні цивільну мандатну адміністрацію й почала керувати країною через верховного комісара. На чолі цивільної адміністрації стояв верховний комісар Герберт Семюел. Арабські повстання та єврейсько-арабські сутички, що почалися того ж року, наклали відбиток на весь мандатний період. Унаслідок цієї події Тверія (Палестина) перейшла під британську цивільну мандатну адміністрацію.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Проголошено Королівство Єгипет — султан Ахмед Фуад прийняв титул короля", "c6ad08d1"], "d": ["18 грудня 1914 року Британія в односторонньому порядку скасувала суверенні права Османської держави на Єгипет і взяла країну під свій протекторат. Коли після війни переговори між Британією та Єгиптом не дали результату, Британія 28 лютого 1922 року знову односторонньою декларацією проголосила Єгипет незалежною державою. 15 березня 1922 року султан Ахмед Фуад прийняв титул короля (малика), і в Єгипті було проголошено монархію. TDV вважає цю незалежність формальною; конституція королівського ладу мала набути чинності 19 квітня 1923 року.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Фортеця Хаджибей (Кацюбіїв) вийшла з-під влади Литви", "382b51e3"], "d": ["Порт Кацюбіїв (Кочубіїв) на північно-західному узбережжі Чорного моря на початку XV століття укріпив великий князь литовський Вітовт. 1480 року фортеця вийшла з-під влади Литви й дістала назву Хаджибей. Наприкінці XV століття узбережжя перейшло під контроль залежного від османів Кримського ханства; пряме ж приєднання краю до османського адміністративного устрою датується 1538 роком.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Грамота Івана IV донським козакам — перша достовірна згадка про Військо Донське", "16c0732e"], "d": ["Відомості про присутність козаків на Дону починаються з середини XVI століття. За російською військовою енциклопедією, старшинство Війська Донського відраховують від 1570 року: того року цар Іван IV надіслав грамоту козакам, які жили на Сіверському Дінці, з проханням допомогти Іванові Новосильцеву, якого відрядили через Азов послом до османського султана, й пообіцяв за це винагородити їх. Це перша достовірна згадка про службу донських козаків Московській державі. Головним осередком козаків спершу були Верхні Роздори, а потім Черкаськ.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Москва заснувала у Воронежі передовий гарнізон проти степу", "89c941fe"], "d": ["Наприкінці XVI століття теперішня Слобідська Україна та верхів'я басейну Дону були безлюдним Диким полем, через яке татари проходили в набіги на Москву. Московський уряд заклав у цьому степу низку передових гарнізонів; Воронеж, заснований 1585 року, був одним із них. У наступні десятиліття ця фортеця разом із Бєлгородом і Курськом стала однією з перших ланок південної оборонної лінії Москви.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Москва заснувала Бєлгород, Оскол і Курськ як передові гарнізони в степу", "4ff3e225"], "d": ["Відсуваючи південний кордон уперед проти кримських набігів, московський уряд 1596 року заклав Бєлгород, Оскол і Курськ як гарнізонні пункти в Дикому полі. Відтоді Бєлгород став містом-фортецею та центром Бєлгородської оборонної лінії завдовжки 300 кілометрів, яка протяглася в наступному столітті.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["Санджак Сіїрт передано з Діярбакира до Бітліського вілаєту — казу Ерух і село Ширнак також приєднали до Бітліса", "3922d040"], "d": ["Коли після Танзімату перейшли від системи еялетів до системи вілаєтів, санджак Сіїрт, який залишався у складі Діярбакирського вілаєту, 1884 року передали до Бітліського вілаєту. За статтею TDV про Ширнак, таким чином і землі, де стоїть нинішній Ширнак, опинилися в казі Ерух санджаку Сіїрт Бітліського вілаєту. Тоді Ширнак був невеликим селом кази Ерух; його назва з'являється в записах наприкінці XIX століття, а центром кази він став у перші роки Республіки. Ці землі були приєднані до Османської держави 1514 року після Чалдиранського походу й управлялися в складі санджаку Сіїрт Діярбакирського еялету.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Мосул і Кіркук перейшли до Сефевідів — після падіння Багдада", "86e176c8"], "d": ["Шах Аббас, який унаслідок подій, що почалися з повстання Бекіра Субаши, захопив Багдад, послав свого полководця Карчакай-хана з військами на Мосул і Кіркук. Намісник Мосула Черкез Ахмед-паша зміг обороняти місто лише кілька днів; Мосул, як і Кіркук, перейшов під владу Ірану, а намісником призначили Касим-хана. Коли перед Мосулом з'явився Сіпагі Кючюк Ахмед, який командував авангардом Хафиз Ахмед-паші, Касим-хан залишив місто й відступив до Багдада, але внаслідок контрнаступу шаха Аббаса Мосул 1624 року знову перейшов до Сефевідів.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Визволення Мосула від Сефевідів — багдадський похід Хафиз Ахмед-паші", "1f9ca4a1"], "d": ["Мурад IV послав на Багдад військо під командуванням великого візира Хафиз Ахмед-паші. Коли військо перебувало поблизу Діярбакира, авангард бейлербея Карамана Черкеза Хасана гнав проіранські сили, зібрані в Алтинкьопрю, аж до Кіркука і взяв під контроль край разом із Кіркуком; Сефевіди й цього разу не змогли довго втримати Мосул. На початку вересня Хафиз Ахмед-паша прибув спершу до Мосула, потім до Кіркука і 13 листопада 1625 року взяв Багдад в облогу; облога виявилася безрезультатною, і Багдад залишився в руках Сефевідів. Натомість стаття TDV про Кіркук відносить повернення міста від Сефевідів до 1630 року й пов'язує його з Хюсрев-пашею.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Хюсрев-паша відбудував фортецю Гюланбер у Шахрізорі — Шахрізорське бейлербейство", "9511853c"], "d": ["Великий візир Хюсрев-паша, який вирушив у багдадський похід, через сильні дощі надовго затримався в Мосулі, а потім повернув на Шахрізор. Почали відбудовувати фортецю Гюланбер, зруйновану з наказу шаха Аббаса під час його навали; Шахрізор знову зробили центром бейлербейства, а бейлербеєм у фортеці залишили Арнавуда Мустафа-пашу. Хюсрев-паша привів до покори місцеві племена, захопив фортецю Мехрібан і 5 травня 1630 року поблизу неї завдав сефевідському війську тяжких втрат.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Тімурташ-бей узяв Кизилджаагач-Єніджесі (Елхово) та Янболу в долині Тунджі", "2c2aebea"], "d": ["Під час кампанії Мурада I проти Болгарії та Візантії Кара Тімурташ-бея послали в долину Тунджі; він захопив Кизилджаагач-Єніджесі та Янболу й повернувся до Едірне з великою здобиччю.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Князівство Деяновичів (Костадін-ілі) стало османським васалом", "54b8dd6c"], "d": ["Коли після поразки на Мариці (під Черноменом) сербська держава розпалася, брати Йован і Костянтин Деяновичі заснували власне князівство з центром у Вельбужді (пізніше Кюстендил), яке охоплювало Штип, Струмицю, Дойран і околиці Кьопрюлю (Велеса). Після скорої смерті Йована Костянтин визнав зверхність Мурада I і став османським васалом; на цих умовах князівство існувало напівнезалежно. Коли 1395 року Костянтин загинув під Ровіне в лавах Баязида Блискавичного, його країна без боротьби перейшла під османське управління й стала санджаком під назвою Костадін-ілі.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["Сербський деспот Стефан Лазаревич узяв Шехіркьой (Пірот)", "87e1ecb3"], "d": ["Поки тривала боротьба між Мусою Челебі, який у добу міжцарів'я панував у Румелії, та його братом Челебі Мехмедом, сербський деспот Стефан Лазаревич захопив фортецю Шехіркьой на шляху між Нішем і Софією та втримав її проти нападу Муси Челебі. Наступного року, після смерті Муси, Челебі Мехмед офіційно залишив фортецю своєму васалові Стефану; османи повернули Шехіркьой лише 1428 року, після смерті Лазаревича.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Андреа Доріа захопив Герцег-Нові (Кастельнуово)", "a8276ff1"], "d": ["Андреа Доріа, командувач союзного флоту, об'єднаного проти османів, захопив фортецю Герцег-Нові (Кастельнуово) на адріатичному узбережжі на півдні Далмації. Того ж року венеційці в Далмації також узяли кілька османських містечок, а османські війська відповіли захопленням інших фортець. Фортецю повернули через рік; оскільки юридично османський суверенітет зберігався, цей проміжний період показано на карті штрихованим шаром окупації.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Барбаросса Хайреддін-паша повернув Герцег-Нові (Кастельнуово)", "1e5b49ae"], "d": ["Османи, які після перемоги під Превезою здобули перевагу й у центральному Середземномор'ї, звернулися проти фортеці Нова (Кастельнуово) на адріатичному узбережжі, яку роком раніше взяв Андреа Доріа. Унаслідок операції, яку спільно провели Барбаросса Хайреддін-паша та боснійський бей Ґазі Хюсрев-бей, фортецю було повернено, і окупація завершилася.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Похід Дезе у Верхній Єгипет — французька дивізія дісталася Міньї, Асьюта та Гірги", "8ff8e4fe"], "d": ["Поки Наполеон перебував у Каїрі, дивізія генерала Дезе, переслідуючи мамлюцькі сили, просувалася долиною Нілу на південь: 21 грудня 1798 року вона дійшла до Міньї, на Різдво — до Асьюта, а 29 грудня — до Гірги. Унаслідок цього маршу, який у лютому 1799 року досяг Асуана, долина між Каїром та Асуаном перейшла під французький контроль.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Наполеон окупував Ель-Аріш — початок сирійського походу", "69dc52ce"], "d": ["Французька армія, яка окупувала Єгипет, прямуючи на Сирію, захопила Ель-Аріш на синайському узбережжі.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Повернення Ель-Аріша від французів", "c25e48a7"], "d": ["Ель-Аріш, окупований Наполеоном у лютому 1799 року, наприкінці грудня того ж року повернуло військо великого візира Юсуфа Зії-паші.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Поразка під Ставучанами та здача Хотина росіянам (російсько-турецька війна 1736–1739 років)", "657d82d2"], "d": ["У кампанії 1739 року головна російська армія під командуванням фельдмаршала Мініха пройшла польськими землями, увійшла в Молдавію і під Ставучанами поблизу Хотина завдала тяжкої поразки війську сераскера Велі-паші. Одразу після цієї битви Хотинська фортеця здалася росіянам, а на початку вересня російські війська увійшли в Ясси. Проте, коли Австрія уклала сепаратний мир, війна завершилася Белградським миром, підписаним того ж місяця.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Російська армія переправилася через Дністер і увійшла в Молдавію (російсько-турецька війна 1768–1774 років)", "938bd834"], "d": ["Приблизно через шість місяців після оголошення війни головна російська армія під командуванням князя Голіцина зібралася на Поділлі. На заклик молдавського митрополита Досифея взяти Молдавію під російське покровительство Голіцин переправився через Дністер і, перш ніж іти на Ясси, спробував узяти Хотин. Ця перша спроба провалилася, і через труднощі з провіантом армія повернулася на Поділля; Хотин упав лише у вересні 1769 року.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Російська Українська армія переправилася через Дністер біля Могилева й увійшла в Молдавію (російсько-турецька війна 1787–1792 років)", "822c7361"], "d": ["У війні, що почалася 1787 року з її оголошення Османською державою, Росія створила дві армії: поки армія Потьомкіна облягала Очаків, Українська армія Рум'янцева мала загрожувати Бендерам між Дністром і Бугом та підтримувати зв'язок з Австрією. Рум'янцев виділив одну колону на підтримку австрійців, які облягали Хотин, а з головними силами переправився через Дністер біля Могилева й увійшов у Молдавію. Так почалася молдавська частина російської операції, яка мала сягнути Ізмаїла та Дунаю.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Російська армія без оголошення війни переправилася через Дністер і почала окупацію Дунайських князівств (російсько-турецька війна 1806–1812 років)", "2094a4d9"], "d": ["У жовтні 1806 року генералові Міхельсону наказали окупувати Молдавію та Волощину; війну ще не було офіційно оголошено. Російські війська почали переправлятися через Дністер, і коменданти фортець Хотин, Бендери, Аккерман і Кілія здали їх без бою. Лише комендант Ізмаїла не піддався на російські умовляння. Висока Порта оголосила війну вже після цієї окупації.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Росіяни захопили Аккерман (1806)", "25aed8d6"], "d": ["Через тиждень після того, як російська армія без оголошення війни переправилася через Дністер, Аккерман захопили війська князя Кантакузіна; татари, які були в місті, залишили його. За Бухарестським миром 1812 року Аккерман разом із Бессарабією відійшов до Росії.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Милорадович увійшов у Бухарест — російська окупація Волощини", "62e4a8e1"], "d": ["Коли російська армія увійшла в Молдавію, комендант Русе Мустафа-паша послав до Бухареста загін, який зайняв місто. Загін генерала Милорадовича вибив його з міста; османські сили відступили до Джурджу. Відтоді до Бухарестського миру 1812 року Бухарест залишався під російською окупацією.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Здача Сілістри росіянам", "d687d04b"], "d": ["Сілістра, яка восени 1809 року витримала облогу Багратіона, у кампанії 1810 року за наказом головнокомандувача Каменського знову опинилася в облозі. Облогові роботи, розпочаті наприкінці травня, тривали кілька днів, і фортеця здалася за умови вільного виходу гарнізону. Тими самими днями штурмом узяли Базарджик (Пазарджик), а Разград упав. Росіяни тримали Сілістру рік; навесні 1811 року Кутузов підірвав мури й залишив фортецю.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Нікополь і Турну (Куле) здалися росіянам без опору", "e297a862"], "d": ["Після капітуляції Русе та Джурджу головнокомандувач Каменський рушив уздовж річки на захід, щоб узяти дунайські фортеці аж до сербського кордону. Нікополь і Турну на протилежному березі здалися без опору; російські загони взяли Плевну, Ловеч і Севлієво та зруйнували їхні укріплення. Росіяни тримали Нікополь шість місяців і в квітні 1811 року залишили його, підірвавши фортецю.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Битва під Русе: Кутузов зруйнував Русе й відійшов на лівий берег Дунаю", "6af4bf85"], "d": ["На початку червня великий візир, виступивши з Шумена, атакував російську армію під Русе, зазнав поразки й відступив на свою укріплену позицію на півдні. Попри цю перемогу, Кутузов вважав перебування в Русе небезпечним; він наказав зруйнувати укріплення фортеці й переправив усі свої сили на лівий берег Дунаю. Великий візир знову зайняв залишене Русе. Так російське утримання міста, яке Каменський прийняв у капітуляцію 26 вересня 1810 року після кривавої облоги, тривало дев'ять місяців. За записом TDV, перед відходом Кутузов наказав підірвати укріплення навколо міста та середньовічну фортецю; у пожежі, що спалахнула, з тридцяти восьми мечетей, які були в місті 1810 року, дванадцять, а з восьми малих мечетей дві було повністю зруйновано. Переправа османської армії через Дунай восени того ж року завершилася облогою під Слобозією.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Російський 6-й піхотний корпус переправився через Прут і увійшов у Дунайські князівства (російсько-турецька війна 1828–1829 років)", "9d9aaaad"], "d": ["Після оголошення Росією війни армія фельдмаршала Вітгенштейна почала дії. 6-й піхотний корпус переправився через Прут і увійшов у Молдавію та Волощину, а його авангард під командуванням генерала Гейсмара попрямував у Малу Волощину. Через кілька днів 7-й корпус узяв в облогу Браїлу, а 3-й корпус готувався переправитися через Дунай між Ізмаїлом і Рені. Дунайські князівства залишалися під російською окупацією до 1834 року.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Здача Сілістри Дибичу — російська окупація, що тривала до 1836 року", "55e28ab1"], "d": ["На початку кампанії 1829 року новий російський головнокомандувач Дибич обрав першою ціллю Сілістру. Гарнізон уперто протидіяв облоговим роботам, якими керував генерал Шильдер; Дибич залишив частину сил під облогою й вийшов у тил великого візира. Облога тривала, і фортеця здалася. Росіяни утримували Сілістру й після закінчення війни — до 1836 року.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Росіяни залишили Сілістру", "4fe2afaf"], "d": ["Після Адріанопольського миру 1829 року росіяни не залишили Сілістру й утримували фортецю до 1836 року. Після відходу російських солдатів валі Селім-паша наказав збудувати посеред напівзруйнованого міста велику однокупольну мечеть.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Російська армія переправилася через Прут і почала окупацію Дунайських князівств (Волощини та Молдавії) — шлях до Кримської війни", "77862041"], "d": ["Коли в суперечці про святі місця в Єрусалимі Висока Порта відхилила вимоги Меншикова, цар Микола I наказав окупувати залежні від османів дунайські князівства «як заставу, доки Туреччина не задовольнить наші справедливі вимоги». Авангард армії під командуванням князя Горчакова переправився через Прут і через дванадцять днів увійшов у Бухарест; слідом головні сили трьома колонами розійшлися по князівствах. Ця окупація без оголошення війни спричинила дипломатичну кризу в Європі, а в жовтні 1853 року — оголошення війни Османською державою; росіяни залишили князівства лише влітку 1854 року під тиском Австрії.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["Мушаашиди осіли в Хувейзі — у Хузестані почалося їхнє правління", "674d0173"], "d": ["Мухаммад ібн Фалах, який виступив із претензією бути Махді, закріпившись серед племен маадів, наступного року зумів осісти в Хувейзі, яка перебувала під контролем Тимуридів. Місто стало центром династії Мушаашидів, що правила в Хузестані.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Шах Ісмаїл приєднав Хувейзу — Мушаашиди стали залежними від Сефевідів намісниками", "7e245f4d"], "d": ["Шах Ісмаїл наказав стратити декого з членів династії Мушаашидів, яких звинуватив у єресі, і підпорядкував область Хувейзи власному управлінню. Відтоді вожді Мушаашидів продовжували існування як залежні від Сефевідів намісники.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["Фортеці Пасін, Шюрегель і Олту відібрано в Сефевідів — між Ерзурумом і Карсом", "68f297aa"], "d": ["Під час походу Сулеймана Законодавця в обидва Іраки фортеці Пасін, Шюрегель і Олту між Ерзурумом і Карсом було відібрано в Сефевідів.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Оздемір-паша взяв порт Массауа", "4cc1d4ad"], "d": ["Бейлербей Хабеського еялету Оздемір-паша, захопивши острови Дахлак, 2 квітня 1557 року взяв місто Массауа на протилежному березі; потім під османське управління перейшло й Аркіко. Так головний порт Абіссинії з виходом до Червоного моря опинився в руках османів.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Приєднання графства Ніцца до Франції", "a140cab2"], "d": ["Після приєднання Савойї в листопаді 1792 року французький Національний конвент 31 січня 1793 року затвердив приєднання до Франції графства Ніцца, яке належало Сардинському королівству; регіон став департаментом Приморські Альпи. Після поразки Наполеона Ніцца за Першим Паризьким миром від 30 травня 1814 року повернулася до Сардинії.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Бій під Рафахом — британсько-анзаківська кіннота взяла позиції Магрунтейн і Рафах", "5053c8ef"], "d": ["Кінна дивізія АНЗАК, бригада Імперського верблюжого корпусу та британська бригада йоменів зі складу Єгипетського експедиційного корпусу, перетнувши Синай, атакували османську позицію з редутами в Магрунтейні, приблизно за кілометр на південь від Рафаха. Після важкого бою прорив новозеландців і верблюжих підрозділів зламав османську оборону; позицію та сусідній Рафах було захоплено, і британські війська вийшли до кордону Палестини.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Зимова операція Казима Карабекіра: разом з Ерзурумом повернено Хасанкале (Пасінлер)", "27df4879"], "d": ["Османські війська під командуванням Казима Карабекір-паші, які після розпаду російської армії почали дії на сході, попри суворі зимові умови повернули Ерзінджан, Ерзурум і Хасанкале на схід від Ерзурума; 25 квітня 1918 року наступ досяг Карса.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Англійці окупували Ескішехір", "8e349037"], "d": ["Після Мудроського перемир'я держави Антанти почали брати під контроль залізничні вузли Анатолії. За статтею TDV про Ескішехір, місто 23 січня 1919 року окупували англійці. Британські частини залишили Ескішехір 20 березня 1920 року.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Висадка італійців на південно-західному узбережжі Анатолії — Мармарис, Бодрум, Кушадаси", "15d6fb7a"], "d": ["Італія, яка залишила Паризьку мирну конференцію на знак протесту проти прогрецької позиції союзників, після Анталії висадила війська на південно-західному узбережжі. За TDV, 5 травня італійці окупували Мармарис, 11 травня — Бодрум, а 13 травня — Кушадаси. Тими самими днями греки висадилися у Фетхіє; суперництво двох держав за Західну Анатолію проклало шлях до окупації Ізміра.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Грецькі війська увійшли в Манісу та Айдин", "a4230775"], "d": ["Грецька армія, що висадилася в Ізмірі 15 травня, швидко поширилася вглиб країни. За статтею TDV про Манісу, грецькі війська увійшли в місто 26 травня 1919 року; за статтею про Айдин, Айдин окупували наступного дня, 27 травня. Окупація Маніси тривала до вересня 1922 року.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Італійська окупація Бурдура — відхід роти, що рушила на Іспарту", "874e9d6d"], "d": ["Італійці, які окупували Анталію, просувалися вглиб країни. За статтею TDV про Іспарту, італійські частини 28 червня окупували Бурдур, а 15 серпня з ротою солдатів рушили на Іспарту. Коли мешканці Іспарти відхилили пропозицію здати зброю й заявили, що чинитимуть опір, італійці наступного дня відступили.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Короткочасне визволення Айдина та повторна окупація 4 липня", "753c739f"], "d": ["Проти грецької окупації в околицях Едеміша, Назіллі та Айдина організувалися національні сили. За статтею TDV про Айдин, місто, окуповане 27 травня 1919 року, 30 червня на короткий час було визволене, але 4 липня знову потрапило під грецьку окупацію. Відтоді місто залишалося окупованим до 7 вересня 1922 року.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Італійська окупація Мугли", "a4f5a926"], "d": ["Італія розширила свою окупацію на південно-західному узбережжі вглиб країни. За статтею TDV про Муглу, місто потрапило під італійську окупацію 23 липня 1919 року. Окупація Мугли тривала до 5 липня 1921 року.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Початок французької військової адміністрації в Західній Фракії", "5801e6de"], "d": ["Західну Фракію, яка належала Болгарії, що програла Першу світову війну, під час мирних переговорів було взято під контроль держав Антанти. За статтею TDV про Західну Фракію, 15 жовтня 1919 року регіон окупували французькі війська; Товариство захисту прав Західної Фракії в цей час перенесло свій осередок у Гюмюльджіне. Французька адміністрація тривала до травня 1920 року, коли за рішенням у Сан-Ремо регіон передали Греції.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Англійці залишили Ескішехір", "6820e164"], "d": ["За статтею TDV про Ескішехір, місто, яке з січня 1919 року перебувало під британською окупацією, англійці залишили 20 березня 1920 року. Через кілька місяців, у червні 1920 року, місто стало осередком Західного фронту, створеного Великими національними зборами Туреччини.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Літній наступ греків — окупація Акхісара, Соми, Баликесіра та Алашехіра", "f096d2b4"], "d": ["Коли союзники дозволили грецькій армії просунутися за лінію Мілна, у Західній Анатолії почався великий грецький наступ. За статтею TDV про національно-визвольну боротьбу, грецькі частини, які 22 червня рушили трьома колонами, захопили Акхісар, Киркагач, Сому та Баликесір. На півдні 26 червня було окуповано Алашехір, а 3 липня — Назіллі.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Грецька окупація Бурси", "7c2b32a1"], "d": ["Північна колона літнього наступу після Баликесіра повернула до Мармурового моря. За статтями TDV про Бурсу та національно-визвольну боротьбу, Бурса потрапила під грецьку окупацію 8 липня 1920 року. Наруга над гробницями перших османських правителів викликала бурхливе обурення по всій країні.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Грецька армія окупувала Східну Фракію — Едірне та Киркларелі", "9eb3bda1"], "d": ["Ще до підписання Севрського договору Греція взялася фактично захопити й Східну Фракію. За статтею TDV про національно-визвольну боротьбу, 20 липня грецька армія захопила всю Фракію; ця подія спонукала султана в Стамбулі через два дні скликати Раду султанату. 26 липня було окуповано Киркларелі, а Едірне того ж місяця також перейшло під грецьку адміністрацію.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Червона армія увійшла в Нахічевань", "6dcb9005"], "d": ["Англійці, які увійшли в регіон на початку 1919 року, ліквідували Араксинську республіку, а влітку того ж року залишили Нахічевань. За статтею TDV про Нахічевань, 28 липня 1920 року Червона армія увійшла в Нахічевань, передала владу комуністам, і було утворено Нахічеванську Радянську Соціалістичну Республіку. Статус регіону визначив договір, підписаний 1921 року в Карсі, — як автономне утворення у складі Азербайджану.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Грецька окупація Ушака", "74ad2713"], "d": ["Грецька армія продовжувала наступ, щоб змусити Анкару прийняти Севрський договір, якого та не визнавала. За статтями TDV про Ушак та національно-визвольну боротьбу, після Гедіза 29 серпня 1920 року було окуповано й Ушак. Мустафа Кемаль-паша приблизно за місяць до цієї окупації інспектував у місті загони національних сил (Куваї-Міллі).", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Грецька окупація Інегьола та Єнішехіра", "4a0460e7"], "d": ["Грецькі частини в Бурсі почали наступати на схід, у напрямку Ескішехіра. За статтею TDV про національно-визвольну боротьбу, 25 жовтня 1920 року було захоплено Інегьол і Єнішехір. Коли стало зрозуміло, що грецький наступ не зупинити силами ополчення, Західний фронт реорганізували на засадах регулярної армії.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Кінець італійської окупації Бурдура (рік)", "609123c8"], "d": ["За статтею TDV про Бурдур, місто, окуповане італійцями 28 червня 1919 року, пережило короткочасну італійську окупацію в 1919–1921 роках. Джерело не називає дня евакуації; на карті окупація закінчується на початку 1921 року. Італія повністю вийшла зі своєї окупаційної зони в Анатолії влітку 1921 року.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Другий грецький наступ — окупація Біледжіка, Афьйона та Адапазари", "9ae146e2"], "d": ["Грецька армія, яка після поразки в Першій битві під Іненю висадила в Ізмірі нові сили, знову перейшла в наступ ще до закінчення строку, наданого Лондонською конференцією. За статтею TDV про національно-визвольну боротьбу, 23 березня греки окупували Біледжік і Афьйон. На півночі 25 березня під грецьку окупацію потрапило й Адапазари.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Турецькі війська залишили Батум", "ba5745dc"], "d": ["Відходячи з Кавказу в липні 1920 року, англійці залишили Батум, а місто захопив уряд Грузії. За статтею TDV про Батум, Московський договір, підписаний із Радянською Росією 16 березня 1921 року, залишив Батум Грузії. 28 березня 1921 року турецькі війська залишили місто, і Батум став центром Аджарської Автономної Республіки, створеної у складі Грузії.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Повернення Афьйона — бої під Асліханларом", "2bbba17b"], "d": ["Після грецького наступу, зупиненого 1 квітня в Другій битві під Іненю, на південному фронті 7 квітня було повернено Афьйон. Стаття TDV про національно-визвольну боротьбу підсумовує це так: «після тяжкої поразки під Асліханларом 7 квітня Афьйон було повернено»; проте праці з воєнної історії відносять бої під Асліханларом і Думлупинаром на час після залишення Афьйона, між 8 і 15 квітня, і зазначають, що тактична перевага залишалася за греками — дві оповіді не узгоджуються між собою, тому наведено обидві. Перемогу під Іненю святкували мітингами по всій країні, насамперед у Стамбулі.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Визволення Ізміта — після Адапазари", "cec60e36"], "d": ["За статтею TDV про Адапазари, місто, яке в березні 1921 року потрапило під грецьку окупацію, було повернено 21 червня. За статтею TDV про Ізміт, місто, яке 6 липня 1920 року окупували спершу англійці, а потім греки, також було визволене 28 червня 1921 року. Залишаючи місто, греки спалили торговий квартал.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Визволення Мугли від італійської окупації", "143ddf98"], "d": ["Італія почала виходити зі своєї окупаційної зони в Анатолії влітку 1921 року; евакуація Анталії почалася 1 червня. За статтею TDV про Муглу, місто, яке з 23 липня 1919 року перебувало під італійською окупацією, було визволене 5 липня 1921 року.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Залишення Ескішехіра — грецька армія увійшла в Ескішехір, Кютах'ю та Біледжік", "a948a74d"], "d": ["Турецька армія, захоплена зненацька в боях під Кютах'єю та Ескішехіром, за наказом Мустафи Кемаля-паші відійшла на схід від Сакар'ї. За статтями TDV, греки увійшли в Ескішехір 20 липня 1921 року, у Кютах'ю — 21 липня, а в Біледжік — 22 липня. Грецький король Костянтин 28 липня головував на військовій раді в Кютах'ї, і армія почала готуватися до наступу в напрямку Анкари.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Італійські війська вийшли з Мармариса та Кушадаси", "1d672994"], "d": ["Італійці, які з травня 1919 року перебували на південно-західному узбережжі Анатолії, після зближення з урядом Анкари крок за кроком залишили свою окупаційну зону. Анталію та Бодрум було залишено влітку 1921 року; останні італійські частини наприкінці квітня 1922 року покинули також Кушадаси та Мармарис.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Почався Великий наступ", "efba4bd3"], "d": ["Після річної підготовки, що тривала від Сакар'ї, турецька армія перейшла в загальний наступ на Афьйонському фронті. За статтями TDV про національно-визвольну боротьбу та Кютах'ю, Великий наступ почався від Афьйона вранці 26 серпня 1922 року, і опір грецької армії швидко було зламано.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Визволення Афьйона", "beaeef23"], "d": ["Другого дня наступу грецький фронт було прорвано під Афьйоном. За статтею TDV про Афьйонкарахісар, унаслідок Великого наступу, яким особисто командував Ататюрк, грецькі війська було вщент розгромлено, і 27 серпня 1922 року місто визволили. Цей день відзначають як день визволення Афьйона.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Битва головнокомандувача — визволення Кютах'ї", "376d3118"], "d": ["Головні сили грецької армії було оточено між Афьйоном і Думлупинаром. За статтею TDV про національно-визвольну боротьбу, операцію з оточення 30 серпня завершила Битва головнокомандувача, якою особисто керував головнокомандувач Мустафа Кемаль-паша. За статтею TDV про Кютах'ю, того ж дня кавалерійська дивізія визволила Кютах'ю, яку спалили й зруйнували грецькі війська під час відступу.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Визволення Ушака", "0f2d44d1"], "d": ["Після Битви головнокомандувача залишки грецької армії відступили на захід, у напрямку Ізміра. За статтею TDV про Ушак, місто, яке з 29 серпня 1920 року перебувало в окупації, було визволене 1 вересня 1922 року, коли в нього увійшли національні сили. У пожежі, яку влаштували окупаційні війська під час відступу, згоріло близько трьох чвертей міста.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Визволення Ескішехіра", "f442de5c"], "d": ["На північному фланзі Великого наступу грецькі війська мусили залишити й Ескішехір. За статтею TDV про Ескішехір, місто, окуповане з 20 липня 1921 року, після перемоги 30 серпня було визволене 2 вересня 1922 року. Наприкінці тринадцятимісячної окупації торговий квартал був спалений, а місто наполовину зруйноване.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Визволення Біледжіка", "35dbd49b"], "d": ["За статтею TDV про Біледжік, під час національно-визвольної боротьби місто тричі потрапляло під грецьку окупацію; третя окупація, що почалася 22 липня 1921 року, завершилася 6 вересня 1922 року. У пожежі, яку грецькі війська влаштували, залишаючи місто, згоріла більша частина будинків, крамниць і урядова будівля.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Визволення Айдина", "ef1280b5"], "d": ["Коли турецька армія наблизилася до Ізміра, відійшли й грецькі війська в долині Великого Мендересу. За статтею TDV про Айдин, 7 вересня 1922 року турецькі війська визволили місто, частково зруйноване і з дуже поменшеним населенням. Греки під час відступу спалили більшу частину міста.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Повернення Бурси", "6ad1da0b"], "d": ["Після визволення Ізміра турецька армія на півночі рушила до узбережжя Мармурового моря. За статтею TDV про Бурсу, місто, яке з 8 липня 1920 року перебувало під грецькою окупацією, було повернене 10–11 вересня 1922 року. Похід армії звідти на Чанаккале стривожив англійців і відкрив шлях до переговорів у Муданьї.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Прийняття Східної Фракії — Киркларелі та Текірдаг", "2a08d65c"], "d": ["Муданійське перемир'я передбачало, що грецька армія залишить Східну Фракію та її буде передано Туреччині; Рефет-паша, якому доручили прийняти Фракію, 19 жовтня прибув до Стамбула. За TDV, Киркларелі, окупований з 26 липня 1920 року, було повернено 10 листопада 1922 року, а Текірдаг також повернули туркам 13 листопада згідно з перемир'ям. Так Східна Фракія без боїв увійшла до турецької території.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Еретна приєднав округи Токата, Кайсері та Самсуна", "4a088f9f"], "d": ["Емір Еретна, який набув сили в Анатолії як намісник Ільханідів, знову здобувши підтримку мамлюцького султана ан-Насіра Мухаммада, 1339 року розширив свої кордони та приєднав округи Токата, Кайсері й Самсуна. Тоді ж під управління Еретни перейшов і округ Заманти на схід від Кайсері. 1341 року, після смерті ан-Насіра, бейлік проголосив незалежність.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Дулкадиридський Халіл-бей розширив кордони до Заманти", "aa911e87"], "d": ["Коли на чолі бейліку Еретни став малолітній Мехмед-бей, на ослаблені землі Еретни почастішали туркменські набіги з півдня. 1360 року, поки туркменський вождь Омер-бей брав Малатью, дулкадиридський Халіл-бей розширив кордони свого бейліку до Заманти на схід від Кайсері. Так округ Заманти між Ельбістаном і Кайсері перейшов до Дулкадиридів, і бейлік утримував цей край до османської анексії 1515 року.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Баязид Блискавичний знову взяв Константинополь у тісну облогу", "244834ca"], "d": ["Константинополь, який з 1391 року періодично перебував у блокаді, навесні 1394 року Баязид Блискавичний знову взяв у тісну облогу. Так стосунки з Візантією, яка з 1371 року платила османам данину й надсилала військову допомогу, перейшли у відкриту ворожнечу. Облогу було знято, коли постала загроза Тимура і 1402 року відбулася битва під Анкарою.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Мир між Мурадом II та Візантією — Візантія знову погодилася платити данину", "6474d704"], "d": ["Мурад II, який 1422 року обложив Константинополь за те, що Візантія підтримала самозванця Мустафу, 22 лютого 1424 року підписав мирний договір з візантійським імператором. За цим договором Візантія знову погодилася платити османам данину й повернути місця, здобуті після 1402 року на узбережжях Мармурового, Егейського та Чорного морів, за винятком фортець Силіврі та Теркос; так повернулася щорічна данина, від якої Візантія звільнилася за угодою з еміром Сулейманом 1403 року. У такому становищі Візантія перебувала до завоювання Константинополя 1453 року.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Фортеці Байбурт і Кігі прийнято від Сефевідів — Ерзінджан і Байбурт віддано Бийиклі Мехмед-бею", "2c7fd65e"], "d": ["Коли султан Селім Явуз, повертаючись після чалдиранської перемоги з Тебріза, стояв табором, надійшли вісті, що фортеці Байбурт і Кігі прийнято під владу. Санджакбей Трапезунда Бийиклі Мехмед-бей і санджакбей Яніни Мустафа-бей у жовтні 1514 року взяли Байбурт, який обороняв Кара Максуд-і Султані, один з емірів шаха Ісмаїла. Ерзінджан, який перейшов під османську владу без бою, разом із Байбуртом 23 жовтня 1514 року віддали Бийиклі Мехмед-бею як бейлербейство, а Байбурт зробили центром санджаку.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Султан Селім Явуз повернувся з тебрізького походу до Амасьї й перезимував там", "49d51f94"], "d": ["Султан Селім Явуз, пробувши в Тебрізі дев'ять днів, через брак продовольства та небажання війська відмовився зимувати в Ірані й повернувся через Карс і Байбурт. Султан, який відсвяткував свято Рамазану в Ніксарі, дістався Амасьї й провів там зиму. Наступного року він мав намір знову виступити проти Сефевідів; в Амасьї почався тиск яничарів із вимогою повернутися до Стамбула, а похід продовжився навесні 1515 року взяттям Кемаха.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Волощина, Молдавія та Трансильванія разом повстали проти османів", "e71d3ee9"], "d": ["У середині 1594 року три воєводства на північ від Дунаю — Волощина, Молдавія та Трансильванія — вирішили спільно діяти проти османів. Молдавський господар Арон Тиран приєднався до Священної ліги, створеної австрійським імператором і папою Климентом VIII, та визнав свою залежність від Трансильванського князівства; волоський господар Михай Хоробрий долучився до руху через невдоволення тяжким податковим тягарем. 13 листопада 1594 року у Волощині та Молдавії одночасно почалися повстання проти османського правління, і за підтримки Трансильванії рух перекинувся на південь від Дунаю, на османські землі. За Енциклопедією ісламу TDV, цей потрійний союз відкрив північний фронт Довгої війни між османами та Габсбургами (1593–1606), яка тривала в ті самі роки.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Завоювання фортеці Островиця в долині Уни", "5c6cc91b"], "d": ["Островиця, яка перебувала в руках Франкопанів та інших хорватських шляхтичів, стояла на крутому хребті, що з'єднував північну та південну частини долини Уни. 1523 року вона перейшла під османське управління й до 1878 року мала османський гарнізон. Справжнього значення фортеця набула після Карловиць (1699): через близькість до венеційського та австрійського кордону її розширили, і вона стала центром капетанства Стара Островиця; на початку XVIII століття біля її підніжжя виникло містечко Кулен-Вакуф.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Завоювання фортець Удбини та Крбави — Ліка переходить під османське управління", "5fe329d3"], "d": ["1524 року Крбавське поле спорожніло, і в Удбині залишився лише гарнізон Карловича. У квітні 1527 року Карлович здобув під фортецею останню перемогу, але наприкінці травня Удбина разом із фортецями Мрсинь і Комич перейшла до рук боснійського паші. Того ж року околиці Госпича віддали агам Сенковичам. Відтоді Ліка та Крбава стали частиною санджаку з центром в Обровці, який 1580 року отримав назву Кирка.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Остаточний перехід Дрежника та Дрежницької жупанії під османське управління", "6624ad14"], "d": ["Дрежник, яким з 1323 року володіли Франкопани, 1578 року османи тимчасово утримували. 1592 року фортеця й уся Дрежницька жупанія остаточно перейшли під османське управління; того ж року впав і Біхач. У XVIII столітті Дрежник підпорядковувався капетанству Острожац.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Узяття фортеці Цетин османами", "98815f97"], "d": ["Цетин, який із середини XVI століття був ключовою фортецею в обороні околиць Слуня від османів, після неодноразових облог 1636 року перейшов під османське управління. Цей перший османський період тривав два роки.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Повернення фортеці Цетин на бік Габсбургів", "690f9f84"], "d": ["Цетин, який 1636 року перейшов до рук османів, 1638 року повернувся до хорватсько-габсбурзької прикордонної оборони й залишався там до 1670 року.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Цетин знову стає османською фортецею", "e1750675"], "d": ["1670 року Цетин знову став османською фортецею, а у XVIII столітті його ґрунтовно укріпили: середньовічну фортецю оточили мурами з бастіонами. До 1790 року фортеця тримала північно-західний край боснійського прикордоння.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Втрата Ліки та Крбави — Удбина та Госпич перейшли до рук габсбурзьких прикордонних сил", "01277a38"], "d": ["У війні, що тривала після поразки під Віднем, хорватські прикордонні частини під проводом карловацького генерала Герберштейна 1689 року взяли Удбину; Госпич того ж року також вийшов з-під османського управління. Османська Ліка, яка проіснувала понад 160 років, припинила існування, спорожнілі місця заселили новим хорватським населенням, а Удбина аж до Систовського миру (1791) була важливою фортецею прикордонної оборони проти османів.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Захоплення Дрежника Австрією — західний фронт Дубицької війни", "05d5e5f1"], "d": ["Під час османсько-австрійської війни 1788-1791 років габсбурзькі сили взяли Дрежник на захід від Біхача. За статтею 4 Систовського договору Дрежник і Цетин залишилися під габсбурзьким управлінням і більше не повернулися до Боснії.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Захоплення фортеці Цетин Австрією", "df182480"], "d": ["1790 року габсбурзьке військо напало на Цетин, Бужим і Велику Кладушу та взяло Цетин. Мобілізація, оголошена боснійським намісником, і контрнаступ не змогли повернути фортецю; стаття 4 Систовського договору залишила Цетин Габсбургам. Боснійські прикордонники ще повертали фортецю під час коротких набігів 1809 та 1813 років.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Біледжік згадується вперше — кордон із Візантією починався в Біледжіку", "7b69f743"], "d": ["Серед подій 683 року, переданих Нешрі, Біледжік фігурує як місце, де починався кордон між прикордонним бейліком Осман-бея та Візантією. Це перша відома в історії згадка про поселення, а не його заснування.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Монета на ім'я Ґазан-хана в Бурдурі — перше відоме свідчення про місто", "01974ddc"], "d": ["Гамідиди під тиском Ільханідів були змушені 699 року карбувати в Бурдурі монету на ім'я Ґазан-хана. Ця монета є першим писемним/датованим свідченням про Бурдур.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Чорум згадується в країні Еретни — перше відоме свідчення про місто", "bf7bd67f"], "d": ["Під час смерті Еретна-бея в мухарамі 753 року Чорум називають серед підвладних йому міст. Час заснування міста невідомий; ця згадка є найранішим датованим свідченням, яке вдалося знайти.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Браїла згадується вперше — привілей Влайку-воде брашовським купцям", "0b3517a7"], "d": ["Волоський господар Владислав видав брашовським купцям грамоту, яка давала їм пільги при перевезенні товарів через Браїлу. Цей документ є першим відомим писемним свідченням про Браїлу; місце фігурує в ньому ще не як місто, а як дунайський кінець шляху. Це не дата заснування.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Кишинів уперше згадано в грамоті молдавського господаря", "a50799d7"], "d": ["Назва Кишинева вперше трапляється в грамоті молдавського господаря Александра 1420 року. Місто довго залишалося невеликим молдавським містечком; коли 1812 року воно разом із Бессарабією перейшло до Росії, то стало обласним центром.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Галац уперше згадано в грамоті молдавського господаря", "a31af8a2"], "d": ["Молдавський господар Штефан II звільнив від мита два вози Хуморського монастиря, які везли рибу з Галаца. Цей документ є першим достовірно відомим писемним свідченням про Галац; раніше поселення могло існувати як рибальське село на березі Дунаю.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Назва Мостара вперше трапляється в дубровницькому документі", "a599bc55"], "d": ["Назва Мостара вперше трапляється в дубровницькому документі, датованому 3 квітня 1452 року; поселення лежало на землях Герцогства Герцеговини. Османське завоювання відбулося 1466–1468 років.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Мечеть Хюнкяра в Сараєві — найраніше датоване свідчення про поселення", "ad697a7d"], "d": ["Санджакбей Боснії Ісхак-бей збудував у першому мусульманському поселенні на Сараєвській рівнині палац для себе, мечеть Хюнкяра на честь султана Мехмеда Фатіха та лазню поруч із нею. Мечеть датується 862 (1458) роком; це найраніша відома датована споруда Сараєва.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Вакфійна грамота Ісхак-бея — міське ядро Сараєва передано у вакф", "0b364229"], "d": ["З вакфійної грамоти Ісхак-бея, датованої джумада аль-уля 866 року (лютий 1462), випливає, що, окрім мечеті та лазні, було збудовано завію, мевлевіхане, імарет, міст через Міляцку, на протилежному березі — Колобарський хан, бедестен, караван-сарай і крамниці. Документ є вакфійною основою міста; поселення існувало й раніше.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Татарпазарджик уперше записано в реєстрі акинджі", "3b1c839e"], "d": ["Найдавніші записи про місто сягають 877 (1472) року: поселення фіксує реєстр акинджі, що зберігається в Національній бібліотеці в Софії.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Баня-Лука вперше згадується в інструкції короля Владислава II", "0ebc6288"], "d": ["Назва Баня-Лука вперше трапляється в інструкції угорсько-хорватського короля Владислава II від 6 лютого 1494 року; край через Яйцький банат був підпорядкований угорській короні. Османське завоювання відбулося взимку 1527–1528 років.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Мешканці Басри завершують переселення на теперішнє місце — стару Басру покинуто", "20f96eac"], "d": ["Мешканці поступово почали оселятися в нинішній Басрі, яку вважали безпечнішою від нападів бедуїнів і де було легше забезпечити себе водою; переїзд на нове місце завершився 900 (1494–1495) року. Стара Басра, заснована за халіфа Умара, була приблизно за 25 км від теперішнього міста.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Хан Менглі Ґерай наказав збудувати Ханський палац біля Чурук-Су — основа Бахчисарая", "0792497c"], "d": ["У долині, яка була місцем літнього полювання та відпочинку намісників Золотої Орди й перших кримських ханів, Менглі Ґерай I наказав збудувати біля Чурук-Су палац, нині відомий як Ханський палац, і цим заклав основу Бахчисарая. Місто розвивалося навколо палацу та вздовж вузької долини Чурук-Су, наприкінці XVI століття розквітло й стало центром Кримського ханства.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Запорозькі козаки заснували першу Січ на острові Хортиця", "e6ca0dd9"], "d": ["Князь Дмитро Вишневецький заснував першу Запорозьку Січ на острові Мала Хортиця на Дніпрі. 1558 року кримські татари обложили й зруйнували фортецю; згодом Січ перемістилася на острови південніше. Термін: «Січ» — це центральний табір запорозьких козаків на дніпровських островах, укріплений колодами та ровами; це ставка, місце зібрання ради та осередок виборного очільника війська (кошового), а не столиця держави.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Засновано Базавлуцьку Січ", "fcd507ae"], "d": ["Після того як татари зруйнували Томаківську Січ, запорозькі козаки заснували нову Січ на острові Базавлук, там, де Дніпро зливається зі своїми рукавами Чортомлик, Підпільна та Скарбна. 1638 року, після придушення козацького повстання, Січ зруйнував польський похід. Термін: «Січ» — це центральний табір запорозьких козаків на дніпровських островах, укріплений колодами та ровами; це ставка, місце зібрання ради та осередок виборного очільника війська (кошового), а не столиця держави. На той час «Гетьманщини» ще не існує (1648); назва «Запорожжя» означає «за порогами», а Січі стоять на степовому пограниччі нижче дніпровських порогів. Етнічної спорідненості з казахами Казахстану козаки не мають: запорозькі козаки — східнослов'янська (українська) православна спільнота; спільним є лише слово «козак» (вільний воїн) тюркського походження.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Микитинську Січ згадано вперше", "61e22abc"], "d": ["Назва четвертої Січі, заснованої на Микитиному Розі на місці теперішнього Нікополя, вперше трапляється 1628 року; 1648 року її захопив Богдан Хмельницький. Це перше відоме свідчення про місце, а не дата його заснування.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Засновано Чортомлицьку Січ", "4b6e8197"], "d": ["Запорозькі козаки заснували Чортомлицьку Січ, яку називають також «Старою Січчю», на мису, де Дніпро зливається з річкою Чортомлик. 25 травня 1709 року російське військо зруйнувало Січ за те, що козаки підтримали Мазепу.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Харків заснували козацькі переселенці", "288b303c"], "d": ["На північному краю Дикого поля, при злитті річок Лопань і Харків, козацькі переселенці з Правобережжя Дніпра заснували поселення. Харків швидко став центром підвладної Москві Слобідської України.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Запорозькі козаки з дозволу кримського хана заснували Олешківську Січ", "ed26f29d"], "d": ["Коли російський наступ змусив залишити Кам'янську Січ, запорозькі козаки з дозволу кримського хана оселилися на землях ханства в Олешках, на лівому березі річки Конка. Після Прутського договору до них приєдналися й козаки Гордієнка. Хан не дозволив Січі мати вали та гармати.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Олешківську Січ пограбовано й покинуто", "52361709"], "d": ["Проросійські самарські козаки напали на Олешківську Січ, пограбували її та підпалили курені. Січ не відновили; козаки 1730 року повернулися до Кам'янки, а 1734 року присягнули на вірність Росії й заснували Нову Січ.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["На Волзі засновано Ставропольську фортецю", "eb087a50"], "d": ["На Середній Волзі для калмиків, які прийняли християнство, заклали фортецю Ставрополь (нинішнє Тольятті).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Надір-шах бере Кандагар і наказує зруйнувати старе місто", "9cc23e6b"], "d": ["Афшарський правитель Надір-шах після тривалої облоги взяв Кандагар, який був у руках афганців-гільзаїв. Місто було зруйноване, а його мешканців переселили в Надірабад, заснований на південний схід від старого місця; старий Кандагар більше ніколи не був містом.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["На Азово-Моздокській лінії засновано Ставропольську фортецю", "7fd9b9f1"], "d": ["На Азово-Моздокській укріпленій лінії, створеній після Кючук-Кайнарджійського миру для контролю над степом між Кубанню та Тереком, збудували десять фортець; однією з них був Ставрополь. Згодом фортеця стала центром Кавказького намісництва та Ставропольської губернії.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["У гирлі Дніпра засновано Херсонську верф", "115f2c34"], "d": ["У гирлі Дніпра, яке після Кючук-Кайнарджійського миру перейшло до Росії, поблизу укріплення Олександр-шанц, спорудженого 1737 року й невдовзі зруйнованого, заклали верф і дали їй назву Херсон. 1784 року місто стало повітовим, а 1803 року — губернським центром.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Греки, переселені з Криму, заснували на азовському узбережжі Маріуполь", "4e3af209"], "d": ["Греки, які прибули з Криму, заснували Маріуполь там, де Кальміус впадає в Азовське море. 1784 року місто стало повітовим центром Катеринославського намісництва.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Катеринослав перенесено на теперішнє місце на Дніпрі", "ec361381"], "d": ["Катеринослав, який Потьомкін заснував 1778 року при злитті річок Кільчень і Самара, через нездорове розташування 1783 року перенесли на теперішнє місце.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["У бухті Ахтіар засновано російський військовий порт Севастополь", "01058a25"], "d": ["Після анексії Криму Росією 1783 року для військового порту обрали бухту, де було кримськотатарське село Ахтіар (Ак'яр); порт заклали наступного року, і він дістав назву Севастополь. 1804 року місто стало головним портом російського Чорноморського флоту.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["У гирлі Бугу закладено укріплення Миколаєва", "d57e52b9"], "d": ["При злитті річок Південний Буг та Інгул з наказу князя Потьомкіна заклали укріплення. 1788 року тут відкрили верф, і поселення стало одним із суднобудівних центрів Чорноморського флоту.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["На Молочній засновано прикордонне поселення — ядро Мелітополя", "637d5817"], "d": ["Після анексії Криму на березі річки Молочної заснували прикордонне поселення. 1816 року воно дістало назву Новоолександрівка, а 1841 року стало містом під назвою Мелітополь.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Засновано Новочеркаськ — новий центр Війська Донського", "bf5709fd"], "d": ["Адміністративний центр Війська Донського перенесли з Черкаська, який був центром до того, у Новочеркаськ, заснований в урочищі Бірючий Кут між річками Аксай і Тузлов.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Ваді-Хальфу зафіксовано під час нубійської подорожі Буркгардта", "6efc72ec"], "d": ["Швейцарський мандрівник Й. Л. Буркгардт у щоденниковому записі від 6 березня 1813 року пише, що проїжджав через Ваді-Хальфу і що там велася невелика торгівля. Це перше датоване свідчення, яке вдалося знайти.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["На азовському узбережжі засновано пристань Бердянськ", "908ac3cf"], "d": ["З ініціативи князя Михайла Воронцова там, де річка Берда впадає в Азовське море, було засновано Бердянськ. 1835 року поселення стало містом, а 1842 року — повітовим центром.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Мешканці Малатьї залишаються в садах Аспузу — ядро сучасної Малатьї", "d1dba159"], "d": ["Влітку 1838 року загальну османську ставку проти єгипетської армії Ібрагім-паші перенесли з Мезраа до Малатьї. Мешканці Малатьї, які жили у своїх літніх будинках в Аспузу, після відходу армії не повернулися до зимових будинків у спустошеному старому місті; Аспузу став ядром сучасної Малатьї. Стара Малатья (Баттал-Газі) й далі існувала, зменшившись.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Ван засновують на новому місці — зруйноване старе місто залишають", "6d278578"], "d": ["2 квітня 1918 року Ван визволили від окупації. Ті, хто повернувся, замість того щоб відбудовувати старий Ван на березі озера, зруйнований у роки війни, заснували нове місто приблизно за 7 км від берега, на місці старих кварталів Норшен і Арак. Старе місто було покинуте.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Мараш перейшов до мамлюків — намісник Алеппо Білбан ат-Табахі повернув його від вірмен", "03171265"], "d": ["Мараш, яким з 1258 року володіло Кілікійське вірменське королівство, 1293 року за договором султана Халіля з вірменами на короткий час перейшов до мамлюків, а після їхнього відходу знову потрапив до рук вірмен. 697 (1298) року мамлюцький намісник Алеппо Білбан ат-Табахі повернув місто. Відтоді Мараш залишався мамлюцькою землею аж до піднесення Зулькадарів.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Візантійська імперія стала данником османів", "615df998"], "d": ["Після перемоги під Чирменом (1371) візантійський імператор Іоанн V узимку 1372 року погодився стати данником Мурада I: він мав сплачувати щорічну данину та давати воїнів для походів султана. Від цієї дати до 1403 року Візантія залишалася залежною від османів васальною державою; блокада Баязида Блискавичного 1391 року збільшила данину. Після поразки під Анкарою Галліпольський договір (1403) з Сулейманом Челебі звільнив Візантію від данини; за договором з Мурадом II 1424 року сплата данини відновилася.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Баязид Блискавичний після смерті Баркука приєднав Бесні, Даренде та Дівригі до османських земель", "8e57d7e6"], "d": ["Після смерті мамлюцького султана Баркука (червень 1399 року), коли в адміністративних справах Мамлюцької держави настав безлад, Баязид Блискавичний спустився в басейн Євфрату й разом із Малатьєю приєднав до османських земель Бесні (Бехісні), Даренде та Дівригі. Сівас ще раніше, після смерті Каді Бурханеддіна влітку 1398 року, залишили османам. Дівригі з 1391 року перебував під мамлюцькою владою й був передовим постом, підпорядкованим провінції Алеппо. Османське управління тут тривало недовго: через наближення загрози Тимура 1401 року Дівригі знову віддали мамлюкам, а остаточно місто перейшло під османське управління після Мардж-Дабіка 1516 року.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Бесні перейшов до мамлюків під час походу Тимура на Сівас і Малатью", "4853da9a"], "d": ["Бесні, який Баязид Блискавичний узяв 1398 року разом із Сівасом, Даренде та Малатьєю, 1400 року, коли Тимур брав Сівас і Малатью, перейшов до рук мамлюків. 27 вересня 1400 року після запеклої облоги Тимур захопив і Бесні; коли він відійшов із того краю, Бесні знову опинився під мамлюцькою владою й залишався в мамлюків (за винятком зулькадарського проміжку), доки в серпні 1516 року його не взяв султан Селім Явуз.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Дівригі через загрозу Тимура знову віддали мамлюкам", "97196b1f"], "d": ["Дівригі, який Баязид Блискавичний 1398 року взяв у мамлюків, 1401 року, коли Тимур наближався до Анатолії, знову залишили мамлюкам. Тому після того, як Тимур зруйнував Сівас (1400), Дівригі на карті має мамлюцький колір; у ті самі місяці Баязид брав на сході Ерзінджан і Кемах, тобто мамлюцька земля опинилася між османськими землями на заході (Сівас) і на північному сході (Кемах). Дівригі остаточно перейшов до османів лише після Мардж-Дабіка 1516 року.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Мамлюцький султан Шейх повернув від Зулькадарів Антеп і Даренде", "f90c9508"], "d": ["Мамлюцький султан Шейх, занепокоєний дружбою Зулькадарів з османами, 1414 року вирушив у похід і повернув Антеп та Даренде, які раніше добровільно віддав Зулькадарам.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Дулкадироглу Мехмед-бей повернув Даренде й приєднав до своїх земель і Бесні", "df914dcb"], "d": ["Даренде, який мамлюки взяли 1414 року, Дулкадироглу Мехмед-бей повернув 1418 року й приєднав до своїх земель також Бесні.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Мамлюки розбили Зулькадарів під Антепом; Бесні повернувся під мамлюцьке управління (приблизно)", "72742430"], "d": ["1436 року мамлюцьке військо розбило Зулькадарів під Антепом, і Мехмед-бей відступив до Акдагу. Рік повернення Бесні до мамлюків у джерелі не вказано; 1418 року Бесні приєднали до Зулькадарів, а до того, як 1465 року Шахсувар-бей відібрав його в мамлюків, місто вже повернулося до них. Атлас повертає Бесні мамлюкам разом із цією поразкою в сусідньому центрі Антепі (задекларована приблизність).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Дулкадироглу Шахсувар-бей відібрав Бесні в мамлюків (приблизно)", "843f0fc4"], "d": ["Шахсувар-бей (1465-1472), якого султан Мехмед Фатіх призначив зулькадарським беєм, захопив Бесні, Герґер, Біреджік і Румкале, що перебували в руках мамлюків; мамлюки зазнали поразки восени 1467 року під Турнадагом і навесні 1468 року поблизу Антепа.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Емір Яшбак розбив Шахсувар-бея; Бесні повернувся під мамлюцьке управління (приблизно)", "4d856aee"], "d": ["Навесні 1471 року емір Яшбак розбив Шахсувар-бея на річці Саврон; мамлюки повернули Кадірлі та Козан. 1472 року Шахсувара стратили в Каїрі, а мамлюки знову поставили беєм Шахбудака. З цим поверненням Бесні також перейшов під мамлюцьке управління (TDV besni: «Наприкінці XV століття знову перейшов до рук мамлюків»).", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Сили Фердинанда зайняли й укріпили Сольнок", "6c8416e6"], "d": ["Коли османи готувалися збудувати фортецю в Сольноку на Тисі, сили Фердинанда I випередили їх: у середині вересня 1550 року вони зайняли Сольнок, а до середини жовтня фортеця стала придатною до оборони. Так Сольнок, що належав до країни Ізабелли, перейшов до рук Габсбургів за рік до переходу Трансильванії до Фердинанда; османи взяли фортецю 1552 року.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Трансильванія перейшла під габсбурзьке управління: сейм у Коложварі визнав зречення Ізабелли", "8458a566"], "d": ["Після угоди Мартінуцці з Фердинандом королева Ізабелла від імені малолітнього короля Яноша Жигмонда 19 червня 1551 року у фортеці Сасшебеш підписала нав'язаний їй акт зречення. Трансильванський сейм, що зібрався 26 липня в Коложварі, визнав це зречення та владу короля Фердинанда; габсбурзьке військо генерала Кастальдо увійшло до Дюлафегервара (Трансильванського Белграда). Так залежна від Османської держави Трансильванія перейшла під габсбурзьке управління, яке тривало п'ять років.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Габсбурзьке управління в Трансильванії закінчилося: вона знову стала залежним від османів воєводством", "721a482a"], "d": ["Через малоліття Яноша Жигмонда Габсбурги 1551 року намагалися опанувати Трансильванію руками призначеного його опікуном священника хорватського походження Мартінуцці (брата Дєрдя); Дюлафегервар, Коложвар, Брашов і Шегешвар п'ять років залишалися під габсбурзьким управлінням. Османи не допустили такого стану, і Трансильванія знову стала залежним від них данницьким воєводством. Після цього впродовж приблизно 150 років у XVI та XVII століттях Трансильванія зберігала статус, що ґрунтувався на широкій автономії у внутрішніх справах і залежності від Стамбула в зовнішніх.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Варад, Хуст і Токай перейшли на бік Запольяї", "587c782d"], "d": ["Після повернення Ізабелли та Яноша Жигмонда до Трансильванії 1556 року прихильники Запольяї того самого року взяли в облогу Надьварад. 1557 року аристократи Верхньої Тиси захопили найважливіші королівські фортеці — Варад, Хуст і Токай; у руках Фердинанда залишилися тільки Дюла та Вілагош. Відтоді Варад став фортецею Трансильванського князівства й залишався нею, доки 1660 року його не взяли османи.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Швенді взяв Сатмар — північний край Трансильванії перейшов до Габсбургів", "2256bb27"], "d": ["Сатмар, який 1561 року, коли Меньхерт Балашша перейшов на інший бік, дістався Габсбургам, восени 1564 року Іштван Баторі повернув раптовим нападом і приєднав до Трансильванії. У лютому 1565 року габсбурзький командувач Лазарус фон Швенді почав контрнаступ: 9 лютого впав Токай, через чотири дні — Серенч, а Сатмар майже без опору перейшов до рук імперських сил.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Сили Бочкаї взяли Сатмар", "e93b098b"], "d": ["Коли повстання Бочкаї поширювалося на північно-східну Угорщину, Дюлаффі 21 січня 1605 року захопив обложений ним Сатмар. Віденський мир від 23 червня 1606 року залишив комітат Сатмар Бочкаї довічно; оскільки спадкоємця чоловічої статі не було, після смерті Бочкаї 29 грудня 1606 року комітат повернувся до корони.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Смерть Іштвана Бочкаї — комітат Сатмар повернувся до корони", "3721bb9b"], "d": ["Трансильванський князь Іштван Бочкаї помер 29 грудня 1606 року в Кошиці. Віденський мир (23 червня 1606 року) залишив йому довічно комітати, зокрема Сатмар, з тим щоб у разі відсутності спадкоємця чоловічої статі вони повернулися до корони; за цим положенням комітат Сатмар знову перейшов до габсбурзького Угорського королівства. Трансильванія почала шукати нового князя.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Габор Бетлен узяв під контроль комітат Сатмар", "80263da1"], "d": ["Унаслідок угорського походу Габора Бетлена восени 1619 року комітат Сатмар перейшов під контроль трансильванського князя; у листопаді 1619 року він звертався до комітату листом. Попередня угода від 23 січня 1620 року та Нікольсбурзький мир залишили Бетленові довічно сім комітатів, зокрема Сатмар. Після смерті Бетлена (15 листопада 1629 року) повернення комітатів короні завершилося 30 березня 1630 року.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Повернення семи комітатів Габора Бетлена короні завершено", "31b5968f"], "d": ["Нікольсбурзький мир залишив Габорові Бетлену довічно сім комітатів Верхньої Угорщини, зокрема Сатмар. Після смерті Бетлена 15 листопада 1629 року повернення комітатів короні почалося з інструкції від 30 листопада 1629 року й завершилося 30 березня 1630 року.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["Дєрдь I Ракоці перейняв Сатмар", "f398635b"], "d": ["Під час походу 1644 року трансильванського князя Дєрдя I Ракоці німецький гарнізон Сатмара перейшов на службу до Ракоці, і фортеця опинилася в руках Трансильванії. Лінцький мир від 16 грудня 1645 року залишив фортецю спадкоємцям Ракоці доти, доки на трансильванському престолі буде хтось із Ракоці.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Втрата Нітри — де Суш повернув фортецю", "c71bf012"], "d": ["Нітру, яка після завоювання Уйвара 1663 року здалася після короткого опору, імперський командувач де Суш 15 квітня 1664 року взяв в облогу; 3 травня 1664 року фортеця здалася. Оскільки Вашварський договір залишав захоплені місця в тому стані, в якому вони перебували, Уйвар залишився османським, а Нітра — в руках Габсбургів.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Втрата Леви", "f311920e"], "d": ["Після Нітри де Суш 9 червня 1664 року взяв в облогу Леву; 13 червня підписали капітуляцію, а 14 червня фортеця була в руках імперських сил. Битва під Левою (Гарамсентбенедеком) 19 липня 1664 року не змінила приналежності; вона завершилася тим, що Габсбурги утримали Леву й Нітру.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Дорошенко здав Чигирин Самойловичу", "3b538237"], "d": ["Гетьман Правобережної України Петро Дорошенко, який перебував під османським протекторатом, 19 вересня 1676 року здав свою столицю Чигирин лівобережному гетьманові Самойловичу та російським силам. Османи усунули Дорошенка й поставили на його місце Юрія Хмельницького; облога 1677 року з метою вигнати російський гарнізон із Чигирина закінчилася невдачею, і фортецю взяли лише 21 серпня 1678 року.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Передача банатських фортець Трансильванії (Темешвар, Ліппа, Лугож, Карансебеш) королю Угорщини Фердинанду", "0e354976"], "d": ["1551 року габсбурзьке військо під проводом генерала Кастальдо увійшло в Трансильванію; королева Ізабелла та її син мусили відмовитися від прав на угорський престол. Мартінуцці зі схвалення Кастальдо в середині липня 1551 року послав Ендре Баторі прийняти від імені Фердинанда фортеці Темешвар, Ліппа, Шоймош, Карансебеш, Лугож, Бече, Бечкерек і Чанад. Так південні фортеці Трансильванії, яка перебувала під османським протекторатом, перейшли до рук Габсбургів; походи Сулеймана Законодавця 1551-1552 років стали відповіддю на це.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Призначення Петера Петровича санджакбеєм Лугожа та Карансебеша", "bcbe73e4"], "d": ["На наполегливе прохання Ізабелли та Петровича Сулейман Законодавець вирішив повернути малого Яноша Жигмонда до Трансильванії. Листом, написаним з Алеппо 7 квітня 1554 року, він наказав трансильванцям повернути дитину в її країну; воєводам Волощини та Молдавії він також звелів допомогти в цій справі Петровичу, якого водночас призначив санджакбеєм Лугожа та Карансебеша. Так Лугож, завойований 1552 року, віддали Петровичу як османський санджак.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Зняття облоги Ліппи — наліт лугозького бана на Темешвар", "be03430e"], "d": ["Навесні 1596 року темешварський паша взяв в облогу Ліппу. У ніч з 10 на 11 травня за наказом трансильванського бана Лугожа Дєрдя Палатича солдати Дєрдя Будая напали на передмістя Темешвара й підпалили їх; те, що Дєрдь Борбей наказав вистрілити з усіх гармат фортеці, також переконало пашу, що прибула підмога. 11 травня паша відійшов від Ліппи й поспішив захищати свій власний центр. Лугож у той час був у руках Трансильванського князівства.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Окупація Оршови австрійськими силами під проводом Ветерані", "1b4a4f6c"], "d": ["Під час походу 1688 року генерал Ветерані, взявши Карансебеш, рушив на Оршову й окупував і її. Дня окупації в джерелі немає; використано основу року — 1 січня 1688 року.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Повернення Оршови силами Текелі та османів", "c5645da9"], "d": ["На Оршову, яку 1688 року окупував Ветерані, після взяття Ветіслана рушили Текелі та османські паші. Після незначних сутичок 15 липня 1689 року Текелі увійшов в Оршову. Гайсслер, прибувши на звістку про небезпеку, побачив, що ворожі сили добре забезпечені боєприпасами та кораблями, і відступив, щоб захищати Трансильванію. Напад Гербевіля під містом у серпні також не зміг повернути Оршову.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Лугозький санджак перейшов під габсбурзьку окупацію (1691-1695)", "c8bcd6bd"], "d": ["Лугозький санджак у 1691-1695 роках залишався під габсбурзькою (німецькою) окупацією; 22 вересня 1695 року Мустафа II знову його завоював. У старому записі проміжок 1689-1695 років був задекларованою прогалиною; відрізок 1691-1695 років тепер зафарбовано як габсбурзький, а 1689-1691 роки залишаються прогалиною. Дату взято лише як рік.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Фортеця Лугож перейшла під габсбурзьке управління", "6a9d401f"], "d": ["Лугож, санджацька фортеця, підпорядкована Темешварському еялету, з 1695 року була в руках османів; після того як центр провінції здався наприкінці облоги 1716 року, її залишили Габсбурзькій монархії. Старий запис датував передачу 1 січня 1716 року — нижньою межею року.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Узяття Оршови габсбурзьким військом (похід 1717 року)", "7a4faffe"], "d": ["Під час походу 1717 року генерал Спленьї 27 серпня підійшов до Оршови й легко захопив місто; так Оршова, яку Мерсі не зміг узяти 1716 року, перейшла до рук Габсбургів. Оскільки навколишні прибережні дунайські комірки (зокрема ділянка Джердапа на сербському боці) прив'язані до найближчого населеного пункту — Оршови, їх зафарбовано кольором її власника. Дату взято лише як рік; точний день не підтверджено.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Перехід паланки Оршови до османів — відхід коменданта в Адакале", "de759b16"], "d": ["На початку походу 1738 року відінський мухафиз Хаджі Мехмед-паша напав на редут Ержебет на Дунаї. Після полудня 8 травня загін сипахів із 4-5 тисяч осіб рушив з лівого берега Дунаю на Оршову й напав на паланку Оршови; австрійський комендант, втративши близько сотні людей, відійшов у Нову Оршову, тобто в острівну фортецю Адакале. Після боїв під Мехадією в липні, в серпні 1738 року Адакале також перейшла до рук османів; Белградський договір 1739 року визнав цей стан.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Мурад II взяв Аладжахісар; Ніш і Шехіркьой повернулися до османів", "54af926a"], "d": ["Після смерті бездітного сербського деспота Стефана Лазаревича (1427) Мурад II, стверджуючи, що на підставі шлюбу Баязида Блискавичного з сербською принцесою він є законним спадкоємцем Сербії, перейшов до дій і взяв Аладжахісар (1428). Того ж року, після смерті Лазаревича, османи повернули також фортецю Шехіркьой — місто Стефан узяв 1412 року й обороняв проти Муси Челебі. Згідно зі статтею TDV про Ніш, того ж року (831/1428) османи повернули й Ніш. Так лінія, що з'єднує долини Великої Морави та Нішави, перейшла під османський контроль.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Армія хрестоносців захопила Шехіркьой — нішавська гілка «Довгого походу»", "fdf6140c"], "d": ["Армія хрестоносців під проводом короля Владислава та сербського деспота Джураджа Бранковича 1443 року захопила Шехіркьой. У продовженні того самого походу в листопаді османські сили зазнають розгрому на Златицькому перевалі. Після Сегедського договору (1444) Мурад II знову віддав Шехіркьой сербам, але після смерті Джураджа Бранковича 1456 року місто перейшло до османів.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["В околицях Аладжахісара встановлено остаточну османську владу", "9715382a"], "d": ["Аладжахісар, залишений Бранковичу за договором з угорськими делегатами 1444 року, у роки після перемоги під Варною знову опинився під турецькою владою. Це друге завоювання міста засвідчене не воєнним, а фінансовим записом: тімарні записи деяких сіл, підпорядкованих Аладжахісару, датуються кінцем 1453 — початком 1454 року; проте це лише свідчення про села — 1454 року османські сили зазнали поразки в околицях Аладжахісара, а 1455 року Аладжахісар залишили Бранковичу як кордон. За TDV, остаточну османську владу в околицях встановлено 1458 року.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Заснування Морейського деспотату — Мануїл Кантакузин у Містрі", "87660b82"], "d": ["Візантійський імператор Іоанн Кантакузин віддав своєму синові Мануїлу окрему адміністративну область у Мореї; так народився Морейський деспотат із центром у Містрі. Мануїл правив до 1380 року; у цей час візантійська культура й мистецтво особливо розквітли в Містрі. Деспотат проіснував до завоювання Фатіхом 1460 року.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Деспот Костянтин відібрав Патри у франків", "cb0dd18c"], "d": ["Морейський деспот Костянтин (1449 року — останній візантійський імператор) повернув Патри від латинян; так цей важливий порт на північному заході півострова також приєднався до деспотату. Під час морейського походу Фатіха 1458 року Патри перейшли під османську владу.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Стефан Вукчич-Косача «герцог Святого Сави» — народження Герцеговини", "cc67061f"], "d": ["Стефан Вукчич-Косача, який об'єднав Хум і Требіньє в одне володіння, повстав проти боснійського короля й проголосив себе «герцогом (герцегом) Святого Сави»; титул 1448 року надав імператор Фрідріх III. Назва Герцеговина («земля герцега») походить від цього титулу. З 1466 року Герцеговина частинами переходила до османів, 1470 року стала санджаком; решту земель приєднали на початку 1482 року.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Краківський мир — держава Тевтонського ордену перетворилася на герцогство Пруссія", "78666ddd"], "d": ["Великий магістр Тевтонських лицарів Альбрехт Бранденбурзький, не знайшовши допомоги проти Польщі, підписав Краківський мир. Орденська держава (Ordensstaat) стала спадковим і світським герцогством під польським сюзеренітетом, що перейшло до бранденбурзької династії. Центром був Кенігсберг; 1544 року Альбрехт заснував тут університет Альбертіну. 1701 року герцогство перетворилося на Прусське королівство.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Проголошення Австрійської Республіки — кінець Габсбурзької монархії", "c84f316c"], "d": ["Наступного дня після того, як 11 листопада імператор Карл I відсторонився від державних справ, Тимчасові національні збори ухвалили закон про форму держави та уряду, і було проголошено республіку. Габсбурзьку Австрію замінила Перша республіка з центром у Відні. Унаслідок цього проголошення Відень, Лінц, Зальцбург, Інсбрук, Клагенфурт, Брегенц та інші німецько-австрійські міста стали територією Австрійської Республіки (Deutschösterreich).", "2dcc1399"]}
});
